package com.osrsflipfinder.runelite;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class RefreshCountdownTest
{
	@Test
	public void formatPollingShowsSecondsUntilNextRefresh()
	{
		long next = System.currentTimeMillis() + 12_500;
		String text = RefreshCountdown.formatPolling(next, true, false);
		assertTrue(text.startsWith("Next refresh in 13s"));
		assertTrue(!text.contains("every"));
	}

	@Test
	public void formatPollingPausedWhenInactive()
	{
		String text = RefreshCountdown.formatPolling(
			System.currentTimeMillis() + 60_000,
			false,
			false
		);
		assertEquals("Refresh paused (switch to this tab to resume)", text);
	}

	@Test
	public void formatPollingRefreshingWhenDue()
	{
		String text = RefreshCountdown.formatPolling(
			System.currentTimeMillis() - 1,
			true,
			false
		);
		assertEquals("Next refresh in 0s", text);
	}

	@Test
	public void formatPollingRefreshingWhenFetchInProgress()
	{
		String text = RefreshCountdown.formatPolling(
			System.currentTimeMillis() + 60_000,
			true,
			true
		);
		assertEquals("Refreshing…", text);
	}

	@Test
	public void combineJoinsNonBlankLines()
	{
		assertEquals("a | b", RefreshCountdown.combine("a", "b"));
		assertEquals("a", RefreshCountdown.combine("a", " "));
		assertEquals(" ", RefreshCountdown.combine(null, null));
	}
}

package com.osrsflipfinder.runelite;

import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class GeSlotSnapshotTest
{
	@Test
	public void boughtAndSoldSlotsAreNotEmpty()
	{
		assertFalse(GeSlotSnapshot.from(0, offer(GrandExchangeOfferState.BOUGHT)).isEmpty());
		assertFalse(GeSlotSnapshot.from(1, offer(GrandExchangeOfferState.SOLD)).isEmpty());
	}

	@Test
	public void activeAndCancelledSlotsMatchOccupancy()
	{
		assertFalse(GeSlotSnapshot.from(0, offer(GrandExchangeOfferState.BUYING)).isEmpty());
		assertFalse(GeSlotSnapshot.from(1, offer(GrandExchangeOfferState.SELLING)).isEmpty());
		assertTrue(GeSlotSnapshot.from(2, offer(GrandExchangeOfferState.EMPTY)).isEmpty());
		assertTrue(GeSlotSnapshot.from(3, offer(GrandExchangeOfferState.CANCELLED_BUY)).isEmpty());
		assertTrue(GeSlotSnapshot.from(4, null).isEmpty());
	}

	private static GrandExchangeOffer offer(GrandExchangeOfferState state)
	{
		GrandExchangeOffer offer = mock(GrandExchangeOffer.class);
		when(offer.getState()).thenReturn(state);
		return offer;
	}
}

package com.osrsflipfinder.runelite;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class GeOfferPriceStrategyTest
{
	@Test
	public void wideMarginAllowsMeaningfulBuySlippage()
	{
		long buy = 500_000L;
		long sell = 980_000L;
		long maxBuy = GeOfferPriceStrategy.maxAggressiveBuyGp(buy, sell, 0);
		assertTrue(maxBuy >= 520_000L);
		long suggested = GeOfferPriceStrategy.suggestedBuyOfferGp(buy, sell, 0);
		assertEquals(maxBuy, suggested);
	}

	@Test
	public void wideMarginBuyWithinBandIsNotOverbid()
	{
		FlipOpportunity opp = new FlipOpportunity();
		opp.setEstimatedBuyPrice(500_000L);
		opp.setEstimatedSellPrice(980_000L);
		opp.setNetProfitPerItem(OfferPriceAnalyzer.estimateNetPerItem(500_000L, 980_000L));

		OfferPriceAnalyzer.Analysis analysis = OfferPriceAnalyzer.analyze(true, 520_000L, opp, 1.0);
		assertNull(analysis.issue);
	}

	@Test
	public void thinMarginStaysNearPlusOne()
	{
		long buy = 100L;
		long sell = 120L;
		long suggested = GeOfferPriceStrategy.suggestedBuyOfferGp(buy, sell, 0);
		assertTrue(suggested >= 101L);
		assertTrue(suggested <= 120L);
	}
}

