package com.osrsflipfinder.runelite;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class IdempotencyKeyBuilderTest
{
	@Test
	public void joinsStablePartsWithColonSeparator()
	{
		String key = IdempotencyKeyBuilder.build(
			"abc123",
			4151,
			"buy",
			1_000_000,
			1,
			1,
			"bought",
			"2026-01-15T12:00:00.000Z",
			0
		);

		assertEquals(
			"abc123:4151:buy:1000000:1:1:bought:2026-01-15T12:00:00.000Z:0",
			key
		);
	}

	@Test
	public void usesNegativeOneSlotWhenOmitted()
	{
		String key = IdempotencyKeyBuilder.build(
			"x",
			1,
			"sell",
			100,
			10,
			5,
			"selling",
			"2026-01-15T12:00:00.000Z",
			null
		);

		assertEquals(true, key.endsWith(":-1"));
	}
}

package com.osrsflipfinder.runelite;

import net.runelite.api.Client;
import net.runelite.api.VarClientInt;
import net.runelite.api.VarClientStr;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class GeOfferChatInputTest
{
	@Test
	public void isOpenWhenInputTypeIsGe()
	{
		Client client = mock(Client.class);
		when(client.getVarcIntValue(VarClientInt.INPUT_TYPE)).thenReturn(GeOfferChatInput.CHAT_INPUT_TYPE_GE);
		assertTrue(GeOfferChatInput.isOpen(client));
	}

	@Test
	public void isClosedWhenNoGeChat()
	{
		Client client = mock(Client.class);
		when(client.getVarcIntValue(VarClientInt.INPUT_TYPE)).thenReturn(0);
		when(client.getVarcIntValue(VarClientID.MESLAYERMODE)).thenReturn(0);
		assertFalse(GeOfferChatInput.isOpen(client));
	}

	@Test
	public void isOtherInputOpenWhenBankPinStyleDialog()
	{
		Client client = mock(Client.class);
		when(client.getVarcIntValue(VarClientInt.INPUT_TYPE)).thenReturn(3);
		when(client.getVarcIntValue(VarClientID.MESLAYERMODE)).thenReturn(3);
		assertTrue(GeOfferChatInput.isOtherInputOpen(client));
	}

	@Test
	public void parseStepRecognizesGePrompts()
	{
		assertEquals(GeOfferChatInput.Step.PRICE, GeOfferChatInput.parseStep("Set a price for each item:"));
		assertEquals(
			GeOfferChatInput.Step.QUANTITY_BUY,
			GeOfferChatInput.parseStep("How many do you wish to buy?")
		);
		assertEquals(
			GeOfferChatInput.Step.QUANTITY_SELL,
			GeOfferChatInput.parseStep("How many do you wish to sell?")
		);
		assertEquals(GeOfferChatInput.Step.NONE, GeOfferChatInput.parseStep("Something else"));
	}

	@Test
	public void prefillWritesChatTextAndVarcs()
	{
		Client client = mock(Client.class);
		Widget mesText2 = mock(Widget.class);
		when(client.getWidget(InterfaceID.Chatbox.MES_TEXT2)).thenReturn(mesText2);

		GeOfferChatInput.prefill(client, 4_200);

		verify(mesText2).setText("4200*");
		verify(client).setVarcStrValue(VarClientStr.INPUT_TEXT, "4200");
	}

	@Test
	public void prefillIfStepRefusesWrongDialog()
	{
		Client client = geChat(GeOfferChatInput.CHAT_INPUT_TYPE_GE, "Set a price for each item:");
		Widget mesText2 = mock(Widget.class);
		when(client.getWidget(InterfaceID.Chatbox.MES_TEXT2)).thenReturn(mesText2);

		assertFalse(GeOfferChatInput.prefillIfStep(client, 50, GeOfferChatInput.Step.QUANTITY_BUY));
		verify(client, never()).setVarcStrValue(VarClientStr.INPUT_TEXT, "50");
	}

	@Test
	public void prefillIfStepAcceptsMatchingPriceDialog()
	{
		Client client = geChat(GeOfferChatInput.CHAT_INPUT_TYPE_GE, "Set a price for each item:");
		Widget mesText2 = mock(Widget.class);
		when(client.getWidget(InterfaceID.Chatbox.MES_TEXT2)).thenReturn(mesText2);

		assertTrue(GeOfferChatInput.prefillIfStep(client, 4_200, GeOfferChatInput.Step.PRICE));
		verify(client).setVarcStrValue(VarClientStr.INPUT_TEXT, "4200");
	}

	private static Client geChat(int inputType, String prompt)
	{
		Client client = mock(Client.class);
		when(client.getVarcIntValue(VarClientInt.INPUT_TYPE)).thenReturn(inputType);
		when(client.getVarcIntValue(VarClientID.MESLAYERMODE)).thenReturn(inputType);
		Widget mesText = mock(Widget.class);
		when(mesText.getText()).thenReturn(prompt);
		when(client.getWidget(InterfaceID.Chatbox.MES_TEXT)).thenReturn(mesText);
		return client;
	}
}

package com.osrsflipfinder.runelite;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.Executors;
import okhttp3.OkHttpClient;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import net.runelite.client.config.ConfigManager;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CopilotClientTest
{
	private MockWebServer server;
	private CopilotClient copilotClient;
	private ItemsClient itemsClient;

	@Before
	public void setUp() throws IOException
	{
		server = new MockWebServer();
		server.start();
		System.setProperty(
			FlipXConstants.BASE_URL_PROPERTY,
			server.url("/").toString().replaceAll("/$", "")
		);

		FlipFinderConfig config = mock(FlipFinderConfig.class);
		when(config.apiKey()).thenReturn("osrs_test");
		when(config.enableOfflineCache()).thenReturn(false);

		PluginApiClient apiClient = new PluginApiClient(
			new OkHttpClient(),
			config,
			mock(ConfigManager.class),
			new Gson()
		);
		LocalCacheStore cacheStore = new LocalCacheStore(new Gson());
		itemsClient = new ItemsClient(
			apiClient,
			config,
			cacheStore,
			Executors.newSingleThreadScheduledExecutor()
		);
		copilotClient = new CopilotClient(itemsClient);
	}

	@After
	public void tearDown() throws IOException
	{
		System.clearProperty(FlipXConstants.BASE_URL_PROPERTY);
		server.shutdown();
	}

	private static String historyBody()
	{
		return "{\"snapshots\":[],\"chartDays\":7,\"meta\":{\"chartDays\":7}}";
	}

	private static String liveBody(int itemId, String name, int score)
	{
		return "{"
			+ "\"opportunity\":{"
			+ "\"id\":" + itemId + ","
			+ "\"name\":\"" + name + "\","
			+ "\"opportunityScore\":" + score + ","
			+ "\"estimatedBuyPrice\":1000000,"
			+ "\"estimatedSellPrice\":1100000,"
			+ "\"netProfitPerItem\":90000,"
			+ "\"netRoiPercent\":9.0,"
			+ "\"confidenceScore\":0.8"
			+ "},"
			+ "\"meta\":{\"lastUpdatedMs\":1700000000000,\"chartDays\":7}"
			+ "}";
	}

	private void enqueueItemResponses(int itemId, String name, int score)
	{
		server.enqueue(new MockResponse()
			.setResponseCode(200)
			.setBody(historyBody()));
		server.enqueue(new MockResponse()
			.setResponseCode(200)
			.setBody(liveBody(itemId, name, score)));
	}

	@Test
	public void fetchCachesByItemId() throws IOException
	{
		enqueueItemResponses(4151, "Abyssal whip", 72);

		CopilotItem first = copilotClient.fetch(4151);
		CopilotItem second = copilotClient.fetch(4151);

		assertEquals("Abyssal whip", first.getName());
		assertEquals(72, second.getOpportunityScore());
		assertEquals(2, server.getRequestCount());
	}

	@Test
	public void fetchBulkPopulatesCache() throws IOException
	{
		enqueueItemResponses(4151, "Abyssal whip", 72);
		enqueueItemResponses(11802, "Armadyl godsword", 65);

		List<CopilotItem> items = copilotClient.fetchBulk(Arrays.asList(4151, 11802));

		assertEquals(2, items.size());
		assertEquals(4, server.getRequestCount());
		assertEquals("Abyssal whip", copilotClient.fetch(4151).getName());
		assertEquals(4, server.getRequestCount());
	}
}

package com.osrsflipfinder.runelite;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class OfferPriceAnalyzerTest
{
	private static final long STAGNATION_SEC = 15 * 60;

	private static FlipOpportunity opp(long buy, long sell)
	{
		FlipOpportunity o = new FlipOpportunity();
		o.setEstimatedBuyPrice(buy);
		o.setEstimatedSellPrice(sell);
		o.setNetProfitPerItem(OfferPriceAnalyzer.estimateNetPerItem(buy, sell));
		return o;
	}

	@Test
	public void waitsBeforeRepriceWhenOverbidAndNotStagnant()
	{
		OfferPriceAnalyzer.Analysis analysis = OfferPriceAnalyzer.analyze(
			true,
			1100,
			opp(1000, 1200),
			1,
			false,
			60,
			0,
			8,
			STAGNATION_SEC
		);
		assertEquals(OfferPriceAnalyzer.Issue.BUY_OVERBID, analysis.issue);
		assertEquals(OfferPriceAnalyzer.Action.WAIT, analysis.action);
		assertTrue(analysis.recommendedPrice > 1000L);
		assertTrue(analysis.recommendedPrice <= 1100L);
	}

	@Test
	public void repricesWhenOverbidAndStagnant()
	{
		OfferPriceAnalyzer.Analysis analysis = OfferPriceAnalyzer.analyze(
			true,
			1100,
			opp(1000, 1200),
			1,
			true,
			1200,
			0,
			8,
			STAGNATION_SEC
		);
		assertEquals(OfferPriceAnalyzer.Action.REPRICE_BUY, analysis.action);
		assertTrue(analysis.recommendedPrice > 1000L);
		assertTrue(analysis.recommendedPrice <= 1100L);
	}

	@Test
	public void waitsWhenUndercutAndNotStagnant()
	{
		OfferPriceAnalyzer.Analysis analysis = OfferPriceAnalyzer.analyze(
			false,
			900,
			opp(800, 1000),
			1,
			false,
			30,
			0,
			8,
			STAGNATION_SEC
		);
		assertEquals(OfferPriceAnalyzer.Issue.SELL_UNDERCUT, analysis.issue);
		assertEquals(OfferPriceAnalyzer.Action.WAIT, analysis.action);
		assertEquals(
			GeOfferPriceStrategy.suggestedSellOfferGp(800, 1000, 0),
			analysis.recommendedPrice
		);
	}

	@Test
	public void repricesWhenUndercutAndStagnant()
	{
		OfferPriceAnalyzer.Analysis analysis = OfferPriceAnalyzer.analyze(
			false,
			900,
			opp(800, 1000),
			1,
			true,
			1000,
			0,
			8,
			STAGNATION_SEC
		);
		assertEquals(OfferPriceAnalyzer.Action.REPRICE_SELL, analysis.action);
	}

	@Test
