import net.runelite.client.ui.FontManager;

/** Watchlist sub-view with styled rows and compact remove control. */
class WatchlistPanel extends SidebarContentPanel
{
	private static final int ROW_HEIGHT = 40;

	private final WatchlistClient watchlistClient;
	private final ItemManager itemManager;
	private final ScheduledExecutorService executorService;
	private final Consumer<String> errorListener;

	private final JLabel statusLabel = PluginUi.caption("Loading watchlist...");
	private final JLabel marketRefreshTimerLabel = PluginUi.caption(" ");
	private final JPanel listContainer = PluginUi.listContainer();

	WatchlistPanel(
		WatchlistClient watchlistClient,
		ItemManager itemManager,
		ScheduledExecutorService executorService,
		Runnable onBack,
		Consumer<String> errorListener
	)
	{
		this.watchlistClient = watchlistClient;
		this.itemManager = itemManager;
		this.executorService = executorService;
		this.errorListener = errorListener;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(LEFT_ALIGNMENT);

		add(PluginUi.subViewHeader("Watchlist", onBack, statusLabel));
		marketRefreshTimerLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		marketRefreshTimerLabel.setAlignmentX(LEFT_ALIGNMENT);
		add(marketRefreshTimerLabel);
		PluginUi.fullWidthGrow(listContainer);
		add(listContainer);
	}

	void load()
	{
		statusLabel.setText("Loading watchlist...");
		listContainer.removeAll();
		listContainer.revalidate();
		listContainer.repaint();

		executorService.execute(() ->
		{
			try
			{
				WatchlistResponse response = watchlistClient.fetch();
				SwingUtilities.invokeLater(() -> render(response));
			}
			catch (IOException e)
			{
				errorListener.accept(e.getMessage());
				SwingUtilities.invokeLater(() -> statusLabel.setText(e.getMessage()));
			}
		});
	}

	private void render(WatchlistResponse response)
	{
		listContainer.removeAll();
		List<WatchlistResponse.WatchlistItem> items = response != null ? response.getItems() : null;
		if (items == null || items.isEmpty())
		{
			statusLabel.setText("No items yet");
			listContainer.add(PluginUi.emptyState("Add items from item detail."));
		}
		else
		{
			int max = response.getMaxItems();
			statusLabel.setText(items.size() + (max > 0 && max < 9999 ? " / " + max : "") + " items");
			for (WatchlistResponse.WatchlistItem item : items)
			{
				listContainer.add(buildRow(item));
				listContainer.add(PluginUi.gap(PluginUi.SPACING_XS));
			}
		}
		listContainer.revalidate();
		listContainer.repaint();
	}

	private JPanel buildRow(WatchlistResponse.WatchlistItem item)
	{
		JPanel row = new SidebarContentPanel();
		row.setLayout(new BorderLayout(PluginUi.SPACING_SM, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, PluginUi.GOLD_DIM),
			BorderFactory.createEmptyBorder(
				PluginUi.SPACING_SM, PluginUi.SPACING_SM, PluginUi.SPACING_SM, PluginUi.SPACING_SM
			)
		));
		row.setAlignmentX(LEFT_ALIGNMENT);
		PluginUi.lockRowHeight(row, ROW_HEIGHT);

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 28));
		icon.setHorizontalAlignment(JLabel.CENTER);
		itemManager.getImage(item.getItemId()).addTo(icon);

		String itemName = item.getItemName() != null ? item.getItemName() : "#" + item.getItemId();
		JLabel name = PluginUi.truncatedLabel(itemName, 20);
		name.setForeground(Color.WHITE);
		name.setFont(FontManager.getRunescapeSmallFont());

		JLabel remove = new JLabel("X");
		remove.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		remove.setFont(FontManager.getRunescapeSmallFont());
		remove.setToolTipText("Remove from watchlist");
		remove.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		remove.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				removeItem(item.getItemId(), row);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				remove.setForeground(PluginUi.NEGATIVE);
				row.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				remove.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});

		row.add(icon, BorderLayout.WEST);
		row.add(name, BorderLayout.CENTER);
		row.add(remove, BorderLayout.EAST);
		SidebarContentPanel.lockWidth(row);
		return row;
	}

	private void removeItem(int itemId, JPanel row)
	{
		executorService.execute(() ->
		{
			try
			{
				watchlistClient.remove(itemId);
				SwingUtilities.invokeLater(() ->
				{
					listContainer.remove(row);
					listContainer.revalidate();
					listContainer.repaint();
				});
			}
			catch (IOException e)
			{
				errorListener.accept(e.getMessage());
			}
		});
	}

	void updateMarketRefreshTimer(String text)
	{
		marketRefreshTimerLabel.setText(text != null ? text : " ");
	}
}

package com.osrsflipfinder.runelite;

import net.runelite.api.GrandExchangeOffer;

/**
 * Resolves per-item trade price for P&amp;L. {@link GrandExchangeOffer#getPrice()} is the
 * player's limit price on the offer form; instant fills execute at the opposing book
 * (see RuneLite GE plugin: {@code trade.getSpent() / trade.getQty()}).
 */
final class GeOfferPricing
{
	private GeOfferPricing()
	{
	}

	static int unitPrice(GrandExchangeOffer offer)
	{
		if (offer == null)
		{
			return 0;
		}

		int filled = offer.getQuantitySold();
		if (filled > 0)
		{
			int spent = offer.getSpent();
			if (spent > 0)
			{
				return spent / filled;
			}
		}

		return offer.getPrice();
	}

	static int limitPrice(GrandExchangeOffer offer)
	{
		return offer == null ? 0 : offer.getPrice();
	}

	/**
	 * Gross sell price for net P&amp;L when the offer may instant-fill above a low limit.
	 */
	static long effectiveSellForNet(
		long limitPrice,
		long marketSellEstimate,
		int quantityFilled,
		long unitFillPrice
	)
	{
		if (quantityFilled > 0 && unitFillPrice > 0)
		{
			return unitFillPrice;
		}
		if (marketSellEstimate > 0 && limitPrice > 0 && limitPrice < marketSellEstimate)
		{
			return marketSellEstimate;
		}
		return limitPrice;
	}

	/**
	 * Buy price for net P&amp;L when the offer may instant-fill below a high limit.
	 */
	static long effectiveBuyForNet(
		long limitPrice,
		long marketBuyEstimate,
		int quantityFilled,
		long unitFillPrice
	)
	{
		if (quantityFilled > 0 && unitFillPrice > 0)
		{
			return unitFillPrice;
		}
		if (marketBuyEstimate > 0 && limitPrice > marketBuyEstimate)
		{
			return marketBuyEstimate;
		}
		return limitPrice;
	}
}

package com.osrsflipfinder.runelite;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

/** GP and percent formatting for the sidebar - full integers with thousands separators. */
final class MarketFormat
{
	private static final DateTimeFormatter UPDATED_CLOCK =
		DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault());
	private MarketFormat()
	{
	}

	static String gp(long value)
	{
		return gpExact(value);
	}

	static String gpExact(long value)
	{
		return String.format("%,d", value);
	}

	/** Compact GP for in-game overlays (e.g. 43.0M). */
	static String gpCompact(long value)
	{
		return gpCompactSigned(value, false);
	}

	static String gpCompactSigned(long value)
	{
		return gpCompactSigned(value, true);
	}

	private static String gpCompactSigned(long value, boolean showPlus)
	{
		long abs = Math.abs(value);
		String prefix = value < 0 ? "-" : (showPlus && value > 0 ? "+" : "");
		if (abs >= 1_000_000_000)
		{
			return prefix + String.format("%.2fB", abs / 1_000_000_000.0);
		}
		if (abs >= 1_000_000)
		{
			return prefix + String.format("%.1fM", abs / 1_000_000.0);
		}
		if (abs >= 10_000)
		{
			return prefix + String.format("%.0fK", abs / 1_000.0);
		}
		return signedGp(value);
	}

	static String signedGp(long value)
	{
		return (value > 0 ? "+" : "") + gp(value);
	}

	static String percent(double value)
	{
		return String.format("%.1f%%", value);
	}

	/** Web-style quantity vs GE buy limit, e.g. {@code 1 / 8} or {@code 2 / -}. */
	static String qtyLimit(long quantity, Integer buyLimit)
	{
		if (buyLimit == null)
		{
			return quantity + " / -";
		}
		return quantity + " / " + buyLimit;
	}

	/** Local clock for price snapshot freshness (aligned with web item detail bar). */
	static String updatedClock(long lastUpdatedMs)
	{
		if (lastUpdatedMs <= 0)
		{
			return "—";
		}
		return UPDATED_CLOCK.format(Instant.ofEpochMilli(lastUpdatedMs));
	}
}

package com.osrsflipfinder.runelite;

import javax.annotation.Nullable;
import net.runelite.client.game.ItemStats;

/**
 * Resolves GE quantity for FlipX buy-limit assist.
 *
 * <p>OSRS enforces a per-item GE buy limit on a rolling 4-hour window (sum of quantities
 * purchased). The client shows current usage on the buy setup panel; FlipX also syncs fills
 * from the plugin for cross-session accuracy.
 */
final class GeFlipxBuyLimit
{
	private GeFlipxBuyLimit()
	{
	}

	/**
	 * Quantity to set on the offer. Never returns {@code Integer.MAX_VALUE} / +1K sentinel values.
	 *
	 * <p>Layer 1: remaining GE buy limit (4h window + synced history). Layer 2: cap by inventory
	 * coins at {@code offerPriceGp} when price and coins are known.
	 *
	 * @param clientBoughtSoFar from {@link GeOfferSetupBuyProgress}, or {@code -1} if unknown
	 * @param offerPriceGp per-item price on the GE setup panel (varbit), or {@code <= 0} to skip coin cap
	 * @param inventoryCoins coins in inventory, or {@code < 0} to skip coin cap
	 */
	static int quantityToApply(
		@Nullable BuyLimitRemaining synced,
		int itemId,
		@Nullable ItemStats itemStats,
		int clientBoughtSoFar,
		int offerPriceGp,
		long inventoryCoins
	)
	{
		int fromLimit = remainingBuyLimitQuantity(synced, itemStats, clientBoughtSoFar);
		return capByInventoryCoins(fromLimit, offerPriceGp, inventoryCoins);
	}

	static int quantityToApply(
		@Nullable BuyLimitRemaining synced,
		int itemId,
		@Nullable ItemStats itemStats,
		int clientBoughtSoFar
	)
	{
		return quantityToApply(synced, itemId, itemStats, clientBoughtSoFar, 0, -1);
	}

	static int capByInventoryCoins(int limitQuantity, int offerPriceGp, long inventoryCoins)
	{
		if (limitQuantity <= 0)
		{
			return 0;
		}
		if (offerPriceGp <= 0 || inventoryCoins < 0)
		{
			return limitQuantity;
		}
		long affordable = inventoryCoins / offerPriceGp;
		if (affordable <= 0)
		{
			return 0;
		}
		return (int) Math.min(limitQuantity, affordable);
	}

	private static int remainingBuyLimitQuantity(
		@Nullable BuyLimitRemaining synced,
		@Nullable ItemStats itemStats,
		int clientBoughtSoFar
	)
	{
		int geLimit = itemStats != null ? itemStats.getGeLimit() : 0;
		Integer apiLimit = synced != null ? synced.getBuyLimit() : null;
		int limit = positiveOrElse(apiLimit, geLimit);

		int bought = Math.max(
			clientBoughtSoFar >= 0 ? clientBoughtSoFar : 0,
			synced != null ? synced.getQuantityBoughtInWindow() : 0
		);

		if (limit > 0)
		{
			return Math.max(0, Math.min(limit - bought, limit));
		}

		if (synced != null && synced.getRemainingQuantity() != null)
		{
			return Math.max(0, synced.getRemainingQuantity());
		}

		return geLimit > 0 ? geLimit : 0;
	}

	/** @deprecated use {@link #quantityToApply(BuyLimitRemaining, int, ItemStats, int, int, long)} */
	static int quantityToApply(
		@Nullable BuyLimitRemaining synced,
		int itemId,
		@Nullable ItemStats itemStats
	)
	{
		return quantityToApply(synced, itemId, itemStats, -1);
	}

	private static int positiveOrElse(Integer primary, int fallback)
	{
		if (primary != null && primary > 0)
		{
			return primary;
		}
		return fallback > 0 ? fallback : 0;
	}
}

