package com.osrsflipfinder.runelite;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class FilterBookmarkStore
{
	private static final int LOCAL_LIMIT = 5;
	private static final Type LIST_TYPE = new TypeToken<List<FilterBookmark>>() {}.getType();

	private final ConfigManager configManager;
	private final Gson gson;

	@Inject
	FilterBookmarkStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	List<FilterBookmark> listLocal(String context)
	{
		String raw = configManager.getConfiguration(FlipFinderConfig.GROUP, configKey(context));
		if (raw == null || raw.isBlank())
		{
			return new ArrayList<>();
		}
		try
		{
			List<FilterBookmark> parsed = gson.fromJson(raw, LIST_TYPE);
			return parsed != null ? parsed : new ArrayList<>();
		}
		catch (RuntimeException e)
		{
			return new ArrayList<>();
		}
	}

	void saveLocal(String context, List<FilterBookmark> bookmarks)
	{
		configManager.setConfiguration(
			FlipFinderConfig.GROUP,
			configKey(context),
			gson.toJson(bookmarks)
		);
	}

	FilterBookmark createLocal(String context, FilterBookmark draft)
	{
		List<FilterBookmark> existing = listLocal(context);
		if (existing.size() >= LOCAL_LIMIT)
		{
			throw new IllegalStateException("bookmark_limit");
		}
		for (FilterBookmark bookmark : existing)
		{
			if (bookmark.getName().equalsIgnoreCase(draft.getName()))
			{
				throw new IllegalStateException("bookmark_name_taken");
			}
		}
		draft.setId("local:" + UUID.randomUUID());
		draft.setContext(context);
		draft.setLocalOnly(true);
		existing.add(draft);
		saveLocal(context, existing);
		return draft;
	}

	void deleteLocal(String context, String id)
	{
		List<FilterBookmark> next = new ArrayList<>();
		for (FilterBookmark bookmark : listLocal(context))
		{
			if (!id.equals(bookmark.getId()))
			{
				next.add(bookmark);
			}
		}
		saveLocal(context, next);
	}

	List<FilterBookmark> merge(List<FilterBookmark> local, List<FilterBookmark> cloud)
	{
		Map<String, FilterBookmark> byName = new LinkedHashMap<>();
		for (FilterBookmark bookmark : local)
		{
			byName.put(bookmark.getName().toLowerCase(), bookmark);
		}
		for (FilterBookmark bookmark : cloud)
		{
			bookmark.setLocalOnly(false);
			byName.put(bookmark.getName().toLowerCase(), bookmark);
		}
		return new ArrayList<>(byName.values());
	}

	private static String configKey(String context)
	{
		return "bookmarks." + context;
	}
}

package com.osrsflipfinder.runelite;

/**
 * Production API endpoints for FlipX. End users never configure these - only
 * developers may override {@link #BASE_URL_PROPERTY} when running locally.
 */
public final class FlipXConstants
{
	static final String BASE_URL_PROPERTY = "flipx.baseUrl";

	private static final String PRODUCTION_BASE_URL = "https://www.flipx.gg";

	private FlipXConstants()
	{
	}

	public static String baseUrl()
	{
		String override = System.getProperty(BASE_URL_PROPERTY);
		if (override != null && !override.isBlank())
		{
			return normalizeBaseUrl(override);
		}
		return PRODUCTION_BASE_URL;
	}

	static String normalizeBaseUrl(String baseUrl)
	{
		if (baseUrl == null)
		{
			return PRODUCTION_BASE_URL;
		}
		String trimmed = baseUrl.trim();
		while (trimmed.endsWith("/"))
		{
			trimmed = trimmed.substring(0, trimmed.length() - 1);
		}
		return trimmed.isEmpty() ? PRODUCTION_BASE_URL : trimmed;
	}

	/** Apex redirects to www on Vercel; treat both as the same API host. */
	static String canonicalBaseUrl(String baseUrl)
	{
		String normalized = normalizeBaseUrl(baseUrl);
		if ("https://flipx.gg".equals(normalized))
		{
			return PRODUCTION_BASE_URL;
		}
		return normalized;
	}
}

package com.osrsflipfinder.runelite;

import com.google.gson.annotations.SerializedName;
import java.io.IOException;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Data;

@Singleton
public class BookmarksClient
{
	private final PluginApiClient apiClient;
	private final FilterBookmarkStore store;

	@Inject
	BookmarksClient(PluginApiClient apiClient, FilterBookmarkStore store)
	{
		this.apiClient = apiClient;
		this.store = store;
	}

	List<FilterBookmark> listMerged(String context, boolean cloudSync)
	{
		List<FilterBookmark> local = store.listLocal(context);
		if (!apiClient.isConfigured() || !cloudSync)
		{
			return local;
		}
		try
		{
			BookmarksResponse response = apiClient.get(
				"/api/plugin/bookmarks?context=" + context,
				BookmarksResponse.class
			);
			if (response == null || response.bookmarks == null || !response.cloudSync)
			{
				return local;
			}
			return store.merge(local, response.bookmarks);
		}
		catch (IOException e)
		{
			return local;
		}
	}

	FilterBookmark save(String context, FilterBookmark draft, boolean cloudSync)
		throws IOException, PluginApiException
	{
		if (apiClient.isConfigured() && cloudSync)
		{
			CreateBookmarkRequest body = CreateBookmarkRequest.from(draft, context);
			CreateBookmarkResponse response = apiClient.post(
				"/api/plugin/bookmarks",
				body,
				CreateBookmarkResponse.class
			);
			if (response != null && response.bookmark != null)
			{
				return response.bookmark;
			}
		}
		return store.createLocal(context, draft);
	}

	void delete(String context, FilterBookmark bookmark, boolean cloudSync)
		throws IOException, PluginApiException
	{
		if (bookmark.getId() != null && bookmark.getId().startsWith("local:"))
		{
			store.deleteLocal(context, bookmark.getId());
			return;
		}
		if (apiClient.isConfigured() && cloudSync && bookmark.getId() != null)
		{
			apiClient.delete("/api/plugin/bookmarks/" + bookmark.getId());
		}
	}

	@Data
	static class BookmarksResponse
	{
		private List<FilterBookmark> bookmarks;
		private boolean cloudSync;
	}

	@Data
	static class CreateBookmarkRequest
	{
		private String context;
		private String name;
		private String presetId;
		private MarketQueryRequest.MarketFilters filters;
		private List<MarketQueryRequest.Sort> sort;
		private Integer volumeEmphasis;

		static CreateBookmarkRequest from(FilterBookmark draft, String context)
		{
			CreateBookmarkRequest req = new CreateBookmarkRequest();
			req.context = context;
			req.name = draft.getName();
			req.presetId = draft.getPresetId();
			req.filters = draft.getFilters();
			req.sort = draft.getSort() != null ? draft.getSort() : Collections.emptyList();
			req.volumeEmphasis = draft.getVolumeEmphasis();
			return req;
		}
	}

	@Data
	static class CreateBookmarkResponse
	{
		private FilterBookmark bookmark;
	}
}

package com.osrsflipfinder.runelite;

/** Wiki-aligned refresh countdown for GE copilot sidebar and overlay. */
final class CopilotRefreshLabels
{
	private CopilotRefreshLabels()
	{
	}

	static String pollingLine(
		OpportunitiesClient opportunities,
		ItemsClient items,
		boolean paired,
		boolean geCopilotActive
	)
	{
		return pollingLine(opportunities, items, paired, geCopilotActive, -1);
	}

	static String pollingLine(
		OpportunitiesClient opportunities,
		ItemsClient items,
		boolean paired,
		boolean geCopilotActive,
		int itemId
	)
	{
		if (!paired)
		{
			return " ";
		}

		long nextAt = resolveNextRefreshAtMs(opportunities, items, itemId);
		boolean pollingActive =
			opportunities.isActive() || geCopilotActive;
		boolean itemFetchBusy = itemId > 0
			? items.isItemFetchInProgress(itemId)
			: items.isItemFetchInProgress();
		return RefreshCountdown.formatPolling(
			nextAt,
			pollingActive,
			opportunities.isFetchInProgress() || itemFetchBusy
		);
	}

	private static long resolveNextRefreshAtMs(
		OpportunitiesClient opportunities,
		ItemsClient items,
		int itemId
	)
	{
		if (itemId > 0)
		{
			long itemNext = items.getNextFetchAtMs(itemId);
			if (itemNext > System.currentTimeMillis())
			{
				return itemNext;
			}
		}

		long marketNext = opportunities.getNextRefreshAtMs();
		if (marketNext > System.currentTimeMillis())
		{
			return marketNext;
		}

		MarketQueryResponse latest = opportunities.getLatest();
		if (latest != null && latest.getMeta() != null)
		{
			PluginEntitlements entitlements = opportunities.getEntitlements();
			long publishLeadMs = entitlements != null && entitlements.getPublishLeadMs() > 0
				? entitlements.getPublishLeadMs()
				: 500L;
			long fallbackMs = entitlements != null && entitlements.getRefreshIntervalMs() > 0
				? entitlements.getRefreshIntervalMs()
				: 60_000L;
			long fromMeta = ClientSchedule.computeNextFetchAtMs(
				latest.getMeta(),
				publishLeadMs,
				fallbackMs,
				System.currentTimeMillis()
			);
			if (fromMeta > System.currentTimeMillis())
			{
				return fromMeta;
			}
		}

		long itemNext = items.getNextWikiRefreshAtMs();
		if (itemNext > System.currentTimeMillis())
		{
			return itemNext;
		}

		return marketNext > 0 ? marketNext : itemNext;
	}

	static String withUpdatedTimestamp(String pollingLine, long lastUpdatedMs)
	{
		String updated = lastUpdatedMs > 0
			? "Updated " + MarketFormat.updatedClock(lastUpdatedMs)
			: null;
		return RefreshCountdown.combine(pollingLine, updated);
	}
}

