package com.osrsflipfinder.runelite;

import net.runelite.api.widgets.Widget;

/** Finds GE setup widgets whether they live in static or dynamic child lists. */
final class GeSetupWidgetSearch
{
	private GeSetupWidgetSearch()
	{
	}

	static Widget findByAction(Widget root, String action)
	{
		return findByAction(root, action, null);
	}

	static Widget findByAction(Widget root, String action, RowBand band)
	{
		if (root == null || action == null)
		{
			return null;
		}
		return findByActionRecursive(root, action, band, 0);
	}

	private static Widget findByActionRecursive(
		Widget widget,
		String action,
		RowBand band,
		int depth
	)
	{
		if (widget == null || depth > 8)
		{
			return null;
		}
		if (matchesAction(widget, action, band))
		{
			return widget;
		}
		Widget direct = scanArray(widget.getChildren(), action, band, depth);
		if (direct != null)
		{
			return direct;
		}
		return scanArray(widget.getDynamicChildren(), action, band, depth);
	}

	private static boolean matchesAction(Widget widget, String action, RowBand band)
	{
		if (band != null && !band.containsY(widget.getOriginalY()))
		{
			return false;
		}
		String[] actions = widget.getActions();
		if (actions == null)
		{
			return false;
		}
		for (String op : actions)
		{
			if (action.equals(op))
			{
				return true;
			}
		}
		return false;
	}

	private static Widget scanArray(Widget[] children, String action, RowBand band, int depth)
	{
		if (children == null)
		{
			return null;
		}
		for (Widget child : children)
		{
			Widget hit = findByActionRecursive(child, action, band, depth + 1);
			if (hit != null)
			{
				return hit;
			}
		}
		return null;
	}

	/** Quantity row (small +/- and +1K band). */
	static RowBand quantityRow()
	{
		return new RowBand(105, 155);
	}

	/** Price row (+5%, Guide price, Enter price band — same Y as big qty buttons). */
	static RowBand priceRow()
	{
		return new RowBand(125, 175);
	}

	static final class RowBand
	{
		private final int minY;
		private final int maxY;

		RowBand(int minY, int maxY)
		{
			this.minY = minY;
			this.maxY = maxY;
		}

		boolean containsY(int y)
		{
			return y >= minY && y <= maxY;
		}
	}
}

package com.osrsflipfinder.runelite;

import java.util.Objects;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

final class OfferSnapshot
{
	private final GrandExchangeOfferState state;
	private final int itemId;
	private final int price;
	private final int quantity;
	private final int quantityFilled;

	private OfferSnapshot(
		GrandExchangeOfferState state,
		int itemId,
		int price,
		int quantity,
		int quantityFilled
	)
	{
		this.state = state;
		this.itemId = itemId;
		this.price = price;
		this.quantity = quantity;
		this.quantityFilled = quantityFilled;
	}

	static OfferSnapshot from(GrandExchangeOffer offer)
	{
		return new OfferSnapshot(
			offer.getState(),
			offer.getItemId(),
			GeOfferPricing.unitPrice(offer),
			offer.getTotalQuantity(),
			offer.getQuantitySold()
		);
	}

	boolean equalsOffer(GrandExchangeOffer offer)
	{
		return state == offer.getState()
			&& itemId == offer.getItemId()
			&& quantity == offer.getTotalQuantity()
			&& quantityFilled == offer.getQuantitySold()
			&& price == GeOfferPricing.unitPrice(offer);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof OfferSnapshot))
		{
			return false;
		}
		OfferSnapshot that = (OfferSnapshot) o;
		return itemId == that.itemId
			&& price == that.price
			&& quantity == that.quantity
			&& quantityFilled == that.quantityFilled
			&& state == that.state;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(state, itemId, price, quantity, quantityFilled);
	}

	GrandExchangeOfferState getState()
	{
		return state;
	}

	int getItemId()
	{
		return itemId;
	}

	int getPrice()
	{
		return price;
	}

	int getQuantity()
	{
		return quantity;
	}

	int getQuantityFilled()
	{
		return quantityFilled;
	}
}

