import java.io.IOException;
import java.util.Objects;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Polls plugin entitlements on a fixed interval while paired, and the market query
 * on each tier-scoped refresh cycle when the Market tab is visible.
 */
@Slf4j
@Singleton
public class OpportunitiesClient
{
	private static final int MIN_REFRESH_SECONDS = 15;
	private static final int POLL_TICK_SECONDS = 1;
	/** Tier changes sync while paired, independent of wiki-aligned market refresh. */
	private static final int ENTITLEMENTS_POLL_SECONDS = 20;

	private final PluginApiClient apiClient;
	private final FlipFinderConfig config;
	private final LocalCacheStore cacheStore;
	private final ItemsClient itemsClient;
	private final ScheduledExecutorService executorService;

	@Getter
	private volatile PluginEntitlements entitlements;
	@Getter
	private volatile MarketQueryResponse latest;
	@Getter
	private volatile boolean offline;
	@Getter
	private volatile java.time.Instant cachedAt;

	private volatile MarketQueryRequest query = new MarketQueryRequest();
	private volatile boolean active = false;
	private volatile long nextRefreshAtMs = 0;
	private volatile long nextEntitlementsPollAtMs = 0;
	@Getter
	private volatile long refreshIntervalMs = MIN_REFRESH_SECONDS * 1000L;
	private final AtomicBoolean fetchInProgress = new AtomicBoolean(false);
	private final AtomicBoolean entitlementsFetchInProgress = new AtomicBoolean(false);

	private final CopyOnWriteArrayList<Consumer<PluginEntitlements>> entitlementsListeners =
		new CopyOnWriteArrayList<>();
	private volatile Consumer<MarketQueryResponse> dataListener = data -> {};
	private volatile Consumer<PluginState> stateListener = state -> {};
	private volatile Consumer<String> errorListener = message -> {};

	private volatile ScheduledFuture<?> alignedRefreshTask;
	private ScheduledFuture<?> pollTask;

	@Inject
	OpportunitiesClient(
		PluginApiClient apiClient,
		FlipFinderConfig config,
		LocalCacheStore cacheStore,
		ItemsClient itemsClient,
		ScheduledExecutorService executorService
	)
	{
		this.apiClient = apiClient;
		this.config = config;
		this.cacheStore = cacheStore;
		this.itemsClient = itemsClient;
		this.executorService = executorService;
	}

	/** Current market query (filters / preset / sort). */
	MarketQueryRequest getQuery()
	{
		return query;
	}

	static boolean sameQuery(MarketQueryRequest a, MarketQueryRequest b)
	{
		return queriesEqual(a, b);
	}

	void setDataListener(Consumer<MarketQueryResponse> listener)
	{
		this.dataListener = listener != null ? listener : data -> {};
	}

	void setEntitlementsListener(Consumer<PluginEntitlements> listener)
	{
		entitlementsListeners.clear();
		if (listener != null)
		{
			entitlementsListeners.add(listener);
		}
	}

	void addEntitlementsListener(Consumer<PluginEntitlements> listener)
	{
		if (listener != null)
		{
			entitlementsListeners.add(listener);
		}
	}

	/** Immediate entitlements fetch (e.g. after pairing). */
	void requestEntitlementsRefresh()
	{
		nextEntitlementsPollAtMs = 0;
		executorService.execute(this::pollEntitlementsIfDue);
	}

	void setStateListener(Consumer<PluginState> listener)
	{
		this.stateListener = listener != null ? listener : state -> {};
	}

	void setErrorListener(Consumer<String> listener)
	{
		this.errorListener = listener != null ? listener : message -> {};
	}

	void start()
	{
		if (pollTask == null)
		{
			nextEntitlementsPollAtMs = 0;
			pollTask = executorService.scheduleWithFixedDelay(
				this::pollLoop,
				POLL_TICK_SECONDS,
				POLL_TICK_SECONDS,
				TimeUnit.SECONDS
			);
		}
	}

	void shutdown()
	{
		active = false;
		cancelAlignedRefresh();
		if (pollTask != null)
		{
			pollTask.cancel(false);
			pollTask = null;
		}
		entitlements = null;
		latest = null;
	}

	long getNextRefreshAtMs()
	{
		return nextRefreshAtMs;
	}

	boolean isActive()
	{
		return active;
	}

	boolean isFetchInProgress()
	{
		return fetchInProgress.get();
	}

	/** Called when the Market tab becomes visible/hidden. */
	void setActive(boolean active)
	{
		boolean wasActive = this.active;
		this.active = active;
		if (active && !wasActive)
		{
			requestImmediateRefresh();
		}
	}

	/** Update the market query and refresh immediately if the tab is visible. */
	void setQuery(MarketQueryRequest query)
	{
		MarketQueryRequest next = query != null ? query : new MarketQueryRequest();
		if (queriesEqual(this.query, next))
		{
			return;
		}
		this.query = next;
		if (active)
		{
			requestImmediateRefresh();
		}
	}

	private static boolean queriesEqual(MarketQueryRequest a, MarketQueryRequest b)
	{
		if (a == b)
		{
			return true;
		}
		if (a == null || b == null)
		{
			return false;
		}
		return java.util.Objects.equals(a.getPresetId(), b.getPresetId())
			&& java.util.Objects.equals(a.getFilters(), b.getFilters())
			&& java.util.Objects.equals(a.getSort(), b.getSort());
	}

	void requestImmediateRefresh()
	{
		nextRefreshAtMs = 0;
		nextEntitlementsPollAtMs = 0;
		executorService.execute(this::pollLoop);
	}

	private void pollLoop()
	{
		pollEntitlementsIfDue();
		tickMarketIfDue();
		itemsClient.tickDueRefreshes();
	}

	private void pollEntitlementsIfDue()
	{
		if (!apiClient.isConfigured())
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (now < nextEntitlementsPollAtMs)
		{
			return;
		}
		if (!entitlementsFetchInProgress.compareAndSet(false, true))
		{
			return;
		}
		try
		{
			refreshEntitlementsOnly();
		}
		finally
		{
			entitlementsFetchInProgress.set(false);
		}
	}

	private void refreshEntitlementsOnly()
	{
		try
		{
			PluginEntitlements freshEntitlements = apiClient.get(
				"/api/plugin/entitlements",
				PluginEntitlements.class
			);
			boolean changed = applyEntitlementsUpdate(freshEntitlements);
			if (changed && active)
			{
				nextRefreshAtMs = 0;
			}
			nextEntitlementsPollAtMs =
				System.currentTimeMillis() + ENTITLEMENTS_POLL_SECONDS * 1000L;
		}
		catch (PluginApiException e)
		{
			nextEntitlementsPollAtMs =
				System.currentTimeMillis() + ENTITLEMENTS_POLL_SECONDS * 1000L;
			if (e.getState() == PluginState.REPAIR_REQUIRED)
			{
				entitlements = null;
			}
		}
		catch (IOException e)
		{
			nextEntitlementsPollAtMs =
				System.currentTimeMillis() + ENTITLEMENTS_POLL_SECONDS * 1000L;
			log.debug("Entitlements poll failed", e);
		}
	}

	private boolean applyEntitlementsUpdate(PluginEntitlements freshEntitlements)
	{
		boolean changed = entitlementsChanged(entitlements, freshEntitlements);
		entitlements = freshEntitlements;
		if (freshEntitlements != null)
		{
			itemsClient.setRefreshIntervalMs(freshEntitlements.getRefreshIntervalMs());
			itemsClient.setPublishLeadMs(freshEntitlements.getPublishLeadMs());
		}
		if (changed)
		{
			for (Consumer<PluginEntitlements> listener : entitlementsListeners)
			{
				listener.accept(freshEntitlements);
			}
		}
		return changed;
	}

	private void tickMarketIfDue()
	{
		if (!active || !apiClient.isConfigured())
		{
			return;
		}
		if (System.currentTimeMillis() < nextRefreshAtMs)
		{
			return;
		}
		if (!fetchInProgress.compareAndSet(false, true))
		{
			return;
		}

		try
		{
			refreshMarketNow();
		}
		finally
		{
			fetchInProgress.set(false);
		}
	}

	private void refreshMarketNow()
	{
		try
		{
			if (entitlements == null)
			{
				PluginEntitlements freshEntitlements = apiClient.get(
					"/api/plugin/entitlements",
					PluginEntitlements.class
				);
				applyEntitlementsUpdate(freshEntitlements);
				nextEntitlementsPollAtMs =
					System.currentTimeMillis() + ENTITLEMENTS_POLL_SECONDS * 1000L;
			}

			MarketQueryResponse response = apiClient.post(
				"/api/plugin/market/query",
				query,
				MarketQueryResponse.class
			);
			latest = response;
			offline = false;
			cachedAt = null;
			cacheStore.write("market", response, config);

			long fallbackMs = tierFallbackIntervalMs();
			refreshIntervalMs = fallbackMs;
			long publishLeadMs = entitlements != null && entitlements.getPublishLeadMs() > 0
				? entitlements.getPublishLeadMs()
				: 500L;
			nextRefreshAtMs = ClientSchedule.computeNextFetchAtMs(
				response.getMeta(),
				publishLeadMs,
				fallbackMs,
				System.currentTimeMillis()
			);
			scheduleAlignedRefresh(nextRefreshAtMs);
			itemsClient.setRefreshIntervalMs(fallbackMs);
			itemsClient.mergeFromMarketResponse(response);

			stateListener.accept(PluginState.CONNECTED);
			errorListener.accept(null);
			dataListener.accept(response);
		}
		catch (PluginApiException e)
		{
			nextRefreshAtMs = System.currentTimeMillis() + tierFallbackIntervalMs();
			if (e.getState() == PluginState.REPAIR_REQUIRED)
			{
				entitlements = null;
			}
			stateListener.accept(e.getState());
			errorListener.accept(e.getMessage());
		}
		catch (IOException e)
		{
			nextRefreshAtMs = System.currentTimeMillis() + tierFallbackIntervalMs();
			offline = true;
			LocalCacheStore.CachedEntry<MarketQueryResponse> cached = cacheStore.read("market", MarketQueryResponse.class, config);
			if (cached != null)
			{
				latest = cached.getPayload();
				cachedAt = cached.getCachedAt();
				dataListener.accept(latest);
			}
			errorListener.accept(e.getMessage());
			log.debug("Market query failed", e);
		}
	}

	private long tierFallbackIntervalMs()
	{
		if (entitlements != null && entitlements.getRefreshIntervalMs() > 0)
		{
			return entitlements.getRefreshIntervalMs();
		}
		return MIN_REFRESH_SECONDS * 1000L;
	}

	static long computeNextRefreshAtMs(
		MarketQueryResponse.Meta meta,
		long publishLeadMs,
		long fallbackIntervalMs,
		long nowMs
	)
	{
		return ClientSchedule.computeNextFetchAtMs(meta, publishLeadMs, fallbackIntervalMs, nowMs);
	}

	private void scheduleAlignedRefresh(long targetAtMs)
	{
		cancelAlignedRefresh();
		long delayMs = Math.max(0, targetAtMs - System.currentTimeMillis());
		alignedRefreshTask = executorService.schedule(
			() -> executorService.execute(this::tickMarketIfDue),
			delayMs,
			TimeUnit.MILLISECONDS
		);
	}

	private void cancelAlignedRefresh()
	{
		if (alignedRefreshTask != null)
		{
			alignedRefreshTask.cancel(false);
			alignedRefreshTask = null;
		}
	}

	static boolean entitlementsChanged(PluginEntitlements before, PluginEntitlements after)
	{
		if (before == null || after == null)
		{
			return before != after;
		}
		return !Objects.equals(before.getTier(), after.getTier())
			|| before.isPaid() != after.isPaid()
			|| before.isUltra() != after.isUltra()
			|| before.isElite() != after.isElite()
			|| before.getMaxOpportunities() != after.getMaxOpportunities()
			|| before.getRefreshIntervalMs() != after.getRefreshIntervalMs()
			|| before.getPublishLeadMs() != after.getPublishLeadMs()
			|| before.getSlotOptimizerSlots() != after.getSlotOptimizerSlots()
			|| before.isQuickPresets() != after.isQuickPresets()
			|| before.isAdvancedFilters() != after.isAdvancedFilters()
			|| before.isCopilotApi() != after.isCopilotApi()
			|| before.isCloudSync() != after.isCloudSync()
			|| before.isPortfolio() != after.isPortfolio()
			|| before.isRecipeFlips() != after.isRecipeFlips()
			|| before.getItemChartDays() != after.getItemChartDays()
			|| before.getWatchlistMaxItems() != after.getWatchlistMaxItems()
			|| before.isVolumeEmphasis() != after.isVolumeEmphasis();
	}
}

package com.osrsflipfinder.runelite;

import java.io.File;
import javax.inject.Inject;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JFileChooser;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import java.util.concurrent.ScheduledExecutorService;
import net.runelite.client.util.LinkBrowser;

/** Flipping Utilities import CTA and optional in-plugin file upload. */
class ImportPanel extends SidebarContentPanel
{
	private final FlipFinderConfig config;
	private final ImportClient importClient;
	private final OpportunitiesClient opportunitiesClient;
	private final ScheduledExecutorService executorService;

	private final JLabel resultLabel = PluginUi.caption(" ");
	private final JButton upgradeButton = PluginUi.upgradeButton("plugin_import");

	@Inject
	ImportPanel(
		FlipFinderConfig config,
		ImportClient importClient,
		OpportunitiesClient opportunitiesClient,
		ScheduledExecutorService executorService
	)
	{
		this.config = config;
		this.importClient = importClient;
		this.opportunitiesClient = opportunitiesClient;
		this.executorService = executorService;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		PluginUi.transparent(this);

		JPanel card = PluginUi.card();
		card.add(PluginUi.cardHint(
			"Flipping Utilities user? Export CSV from the Stats tab, then import on the web or pick a file below."
		));
		card.add(PluginUi.gap(PluginUi.SPACING_SM));
		card.add(PluginUi.cardHint(
			"File import requires pairing and sends your export to FlipX (flipx.gg) over HTTPS. "
				+ "See Privacy in Connection or flipx.gg/privacy."
		));
		card.add(PluginUi.gap(PluginUi.SPACING_MD));

		JButton webButton = PluginUi.externalLinkButton("Import on web");
		webButton.addActionListener(e ->
			LinkBrowser.browse(FlipXConstants.baseUrl() + "/settings/import")
		);
		PluginUi.fullWidth(webButton);
		card.add(webButton);
		card.add(PluginUi.gap(PluginUi.SPACING_SM));

		JButton fileButton = PluginUi.secondaryButton("Choose CSV file...");
		fileButton.addActionListener(e -> chooseFile());
		PluginUi.fullWidth(fileButton);
		card.add(fileButton);
		card.add(PluginUi.gap(PluginUi.SPACING_SM));
		card.add(resultLabel);
		card.add(PluginUi.gap(PluginUi.SPACING_SM));
		PluginUi.fullWidth(upgradeButton);
		upgradeButton.setVisible(false);
		card.add(upgradeButton);
		add(card);

		opportunitiesClient.addEntitlementsListener(entitlements ->
			SwingUtilities.invokeLater(() ->
				PluginUi.syncUpgradeButton(upgradeButton, entitlements)
			)
		);
	}

	private void chooseFile()
	{
		PluginEntitlements entitlements = opportunitiesClient.getEntitlements();
		if (entitlements == null || !entitlements.isPortfolio())
		{
			resultLabel.setText("Pair your device to import on Free (1 lifetime import).");
			return;
		}

		JFileChooser chooser = new JFileChooser();
		chooser.setDialogTitle("Select Flipping Utilities export");
		chooser.setFileFilter(new javax.swing.filechooser.FileNameExtensionFilter(
			"Flipping Utilities exports (*.csv, *.json)", "csv", "json"
		));
		if (chooser.showOpenDialog(this) != JFileChooser.APPROVE_OPTION)
		{
			return;
		}
		File file = chooser.getSelectedFile();
		if (file == null)
		{
			return;
		}

		resultLabel.setText("Importing...");
		executorService.execute(() ->
		{
			try
			{
				ImportClient.ImportResult result = importClient.importFile(file.toPath());
				final String successMessage = result.getSkippedRows() > 0
					? "Imported " + result.getInserted() + " events ("
						+ result.getSkipped() + " duplicates skipped, "
						+ result.getSkippedRows() + " rows skipped)"
					: "Imported " + result.getInserted() + " events ("
						+ result.getSkipped() + " duplicates skipped)";
				SwingUtilities.invokeLater(() -> resultLabel.setText(successMessage));
			}
			catch (PluginApiException ex)
			{
				SwingUtilities.invokeLater(() -> resultLabel.setText(
					ex.getMessage() != null ? ex.getMessage() : "Import failed"
				));
			}
			catch (Exception ex)
			{
				SwingUtilities.invokeLater(() -> resultLabel.setText(
					"Import failed - use a Flipping Utilities CSV export from Stats"
				));
			}
		});
	}
}

package com.osrsflipfinder.runelite;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;

/** Live GE slot occupancy from the game client (must run on client thread). */
final class GeSlotOccupancy
{
	static final int GE_SLOT_COUNT = 8;

	@Value
	static class Snapshot
	{
		int totalSlots;
		int occupiedSlots;
		int emptySlots;
		List<Integer> occupiedItemIds;
		/** Zero-based GE indices that are free (EMPTY). */
		List<Integer> emptySlotIndices;
	}

	static Snapshot read(Client client)
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		int occupied = 0;
		List<Integer> itemIds = new ArrayList<>();
		List<Integer> emptyIndices = new ArrayList<>();
		if (offers != null)
		{
			for (int slot = 0; slot < Math.min(GE_SLOT_COUNT, offers.length); slot++)
			{
				GeSlotSnapshot snap = GeSlotSnapshot.from(slot, offers[slot]);
				if (snap.isEmpty())
				{
					emptyIndices.add(slot);
					continue;
				}
				occupied++;
				GrandExchangeOffer offer = offers[slot];
				if (offer != null && offer.getItemId() > 0)
				{
					itemIds.add(offer.getItemId());
				}
			}
		}
		else
		{
			for (int slot = 0; slot < GE_SLOT_COUNT; slot++)
			{
				emptyIndices.add(slot);
			}
		}
		int empty = Math.max(0, GE_SLOT_COUNT - occupied);
		return new Snapshot(
			GE_SLOT_COUNT,
			occupied,
			empty,
			Collections.unmodifiableList(itemIds),
			Collections.unmodifiableList(emptyIndices)
		);
	}

	private GeSlotOccupancy()
	{
	}
}

package com.osrsflipfinder.runelite;

import net.runelite.client.config.ConfigManager;

/** Reads persisted flipx config keys without relying on a stale {@link FlipFinderConfig} proxy. */
final class FlipFinderConfigIO
{
	private FlipFinderConfigIO()
	{
	}

	static boolean getBoolean(ConfigManager configManager, String key, boolean defaultValue)
	{
		String raw = configManager.getConfiguration(FlipFinderConfig.GROUP, key);
		if (raw == null || raw.isBlank())
		{
			return defaultValue;
		}
		return "true".equalsIgnoreCase(raw);
	}

	static String getString(ConfigManager configManager, String key, String defaultValue)
	{
		String raw = configManager.getConfiguration(FlipFinderConfig.GROUP, key);
		if (raw == null)
		{
			return defaultValue;
		}
		return raw;
	}
}

package com.osrsflipfinder.runelite;

public final class IdempotencyKeyBuilder
{
	private IdempotencyKeyBuilder()
	{
	}

	public static String build(
		String accountHash,
		int itemId,
		String side,
		int price,
		int quantity,
		int quantityFilled,
		String state,
		String occurredAt,
		Integer slot
	)
	{
		int slotValue = slot != null ? slot : -1;
		return accountHash + ':'
			+ itemId + ':'
			+ side + ':'
			+ price + ':'
			+ quantity + ':'
			+ quantityFilled + ':'
			+ state + ':'
			+ occurredAt + ':'
			+ slotValue;
	}

	/** Stable key for RuneLite GE tradeHistory backfill (no timestamp in key). */
	public static String importHistory(
		String accountHash,
		int itemId,
		String side,
		int price,
		int quantity,
		String state,
		long epochSecond
	)
	{
		return "import:runelite-ge:"
			+ accountHash + ':'
			+ itemId + ':'
			+ side + ':'
			+ price + ':'
			+ quantity + ':'
			+ state + ':'
			+ epochSecond;
	}
}

package com.osrsflipfinder.runelite;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/** Builds the GE copilot sidebar body for a resolved {@link FlipOpportunity}. */
final class GeCopilotUi
{
	private GeCopilotUi()
	{
	}

	static JPanel buildBody(ItemManager itemManager, int itemId, FlipOpportunity opp)
	{
		JPanel root = new JPanel();
		root.setLayout(new BoxLayout(root, BoxLayout.Y_AXIS));
		PluginUi.transparent(root);
		root.setAlignmentX(JPanel.LEFT_ALIGNMENT);

		FlipCopilotPresenter.Verdict verdict = FlipCopilotPresenter.verdict(opp);

		root.add(itemHeader(itemManager, itemId, opp.getName()));
		root.add(PluginUi.gap(PluginUi.SPACING_SM));
		root.add(verdictBadge(verdict));
		root.add(PluginUi.gap(PluginUi.SPACING_SM));
		root.add(heroMetrics(opp));
		root.add(PluginUi.gap(PluginUi.SPACING_SM));
		root.add(priceCard(opp));
		root.add(PluginUi.gap(PluginUi.SPACING_SM));
		root.add(flipSizeCard(opp));
		root.add(PluginUi.gap(PluginUi.SPACING_SM));
		root.add(speedCard(opp));
		root.add(PluginUi.gap(PluginUi.SPACING_SM));
		root.add(scoreCard(opp, verdict));

		String hint = FlipCopilotPresenter.repriceHint(opp);
		if (hint != null)
		{
			root.add(PluginUi.gap(PluginUi.SPACING_XS));
			root.add(callout(hint, PluginUi.WARNING));
		}
		if (opp.isPriceDumped())
		{
			root.add(PluginUi.gap(PluginUi.SPACING_XS));
			root.add(callout("Dump flag: price crashed vs recent hourly norms.", PluginUi.NEGATIVE));
		}

		root.add(PluginUi.gap(PluginUi.SPACING_XS));
		root.add(PluginUi.wrappedCaption(FlipCopilotPresenter.actionSummary(opp)));

		SidebarContentPanel.lockWidth(root);
		return root;
	}

	private static JPanel itemHeader(ItemManager itemManager, int itemId, String name)
	{
		JPanel card = PluginUi.card();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 28));
		icon.setAlignmentX(Component.LEFT_ALIGNMENT);
		itemManager.getImage(itemId).addTo(icon);
		String safe = name != null ? name : "Item";
		JLabel title = PluginUi.wrappedBody(safe, PluginUi.cardBodyWrapWidth(), Color.WHITE, true);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		title.setToolTipText(safe.length() > 40 ? safe : null);
		card.add(icon);
