package com.osrsflipfinder.runelite;

import java.util.function.LongConsumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;

/** Reads the coin stack from the local inventory - no network access. */
@Singleton
class CoinBalanceService
{
	private final Client client;
	private final ClientThread clientThread;
	private volatile long coins = -1;
	private volatile LongConsumer balanceListener = value -> {};

	@Inject
	CoinBalanceService(Client client, ClientThread clientThread)
	{
		this.client = client;
		this.clientThread = clientThread;
	}

	void start()
	{
		clientThread.invokeLater(this::refresh);
	}

	/** Notified on the Swing thread whenever the detected coin balance changes. */
	void setBalanceListener(LongConsumer listener)
	{
		this.balanceListener = listener != null ? listener : value -> {};
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			clientThread.invokeLater(this::refresh);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.INVENTORY.getId())
		{
			clientThread.invokeLater(this::refresh);
		}
	}

	void refresh()
	{
		long previous = coins;
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		coins = inventory == null ? -1 : inventory.count(ItemID.COINS);
		if (coins != previous)
		{
			long snapshot = coins;
			javax.swing.SwingUtilities.invokeLater(() -> balanceListener.accept(snapshot));
		}
	}

	long getCoins()
	{
		return coins;
	}

	boolean hasCoins()
	{
		return coins >= 0;
	}
}

package com.osrsflipfinder.runelite;

import java.time.Instant;
import net.runelite.client.config.ConfigManager;

/** Local pairing state - must match {@link FlipXConstants#baseUrl()}. */
final class PairingCredentials
{
	private static final long PAIRING_GRACE_MS = 60_000L;
	private static volatile long lastPairSaveMs = 0L;

	private PairingCredentials()
	{
	}

	static boolean isWithinPairingGracePeriod()
	{
		return System.currentTimeMillis() - lastPairSaveMs < PAIRING_GRACE_MS;
	}

	static void clearIfAuthFailedForKey(
		ConfigManager configManager,
		FlipFinderConfig config,
		String apiKeyUsed
	)
	{
		if (apiKeyUsed == null || apiKeyUsed.isBlank())
		{
			return;
		}
		if (!apiKeyUsed.equals(config.apiKey()))
		{
			return;
		}
		if (isWithinPairingGracePeriod())
		{
			return;
		}
		clear(configManager);
	}

	static boolean isPaired(FlipFinderConfig config)
	{
		return config.apiKey() != null && !config.apiKey().isBlank();
	}

	static boolean isPairedForCurrentApi(FlipFinderConfig config)
	{
		if (!isPaired(config))
		{
			return false;
		}
		String pairedBase = config.pairedBaseUrl();
		if (pairedBase == null || pairedBase.isBlank())
		{
			return true;
		}
		return FlipXConstants.canonicalBaseUrl(pairedBase).equals(FlipXConstants.canonicalBaseUrl(FlipXConstants.baseUrl()));
	}

	/**
	 * Clears stored credentials when the JVM points at a different API host
	 * (e.g. localhost dev client -> production flipx.gg).
	 *
	 * @return true if credentials were cleared
	 */
	static boolean clearIfApiHostChanged(ConfigManager configManager, FlipFinderConfig config)
	{
		if (!isPaired(config))
		{
			return false;
		}
		if (isPairedForCurrentApi(config))
		{
			return false;
		}
		clear(configManager);
		return true;
	}

	static void save(ConfigManager configManager, String apiKey)
	{
		lastPairSaveMs = System.currentTimeMillis();
		configManager.setConfiguration(FlipFinderConfig.GROUP, "apiKey", apiKey);
		configManager.setConfiguration(
			FlipFinderConfig.GROUP,
			"pairedAt",
			Instant.now().toString()
		);
		configManager.setConfiguration(
			FlipFinderConfig.GROUP,
			"pairedBaseUrl",
			FlipXConstants.canonicalBaseUrl(FlipXConstants.baseUrl())
		);
	}

	static void clear(ConfigManager configManager)
	{
		configManager.unsetConfiguration(FlipFinderConfig.GROUP, "apiKey");
		configManager.unsetConfiguration(FlipFinderConfig.GROUP, "pairedAt");
		configManager.unsetConfiguration(FlipFinderConfig.GROUP, "pairedBaseUrl");
	}
}

package com.osrsflipfinder.runelite;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Display-only borders on GE offer slots when FlipX detects a pricing issue.
 * Only drawn on the slot grid — hidden in offer details/setup.
 */
class GeSlotHighlightOverlay extends Overlay
{
	private static final int SLOT_COUNT = 8;

	private final Client client;
	private final FlipFinderConfig config;
	private final ItemsClient itemsClient;
	private final GeSlotTracker slotTracker;

	@Inject
	GeSlotHighlightOverlay(
		Client client,
		FlipFinderConfig config,
		ItemsClient itemsClient,
		GeSlotTracker slotTracker
	)
	{
		this.client = client;
		this.config = config;
		this.itemsClient = itemsClient;
		this.slotTracker = slotTracker;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableGeSlotHighlights())
		{
			return null;
		}

		if (!GeItemResolver.isSlotGridVisible(client))
		{
			return null;
		}

		Widget universe = client.getWidget(InterfaceID.GeOffers.UNIVERSE);
		if (universe == null || universe.isSelfHidden())
		{
			return null;
		}

		Rectangle geWindow = universe.getBounds();
		if (geWindow == null || geWindow.width <= 0 || geWindow.height <= 0)
		{
			return null;
		}

		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return null;
		}

		long stagnationSec = config.tradeStagnationMinutes() * 60L;
		List<ColoredRect> highlights = new ArrayList<>();

		for (int slot = 0; slot < Math.min(SLOT_COUNT, offers.length); slot++)
		{
			GrandExchangeOffer offer = offers[slot];
			if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}

			Color border = borderForSlot(slot, offer, stagnationSec);
			if (border == null)
			{
				continue;
			}

			Rectangle canvas = GeSlotBounds.boundsForSlot(client, slot);
			if (canvas == null || !geWindow.intersects(canvas))
			{
				continue;
			}

			highlights.add(new ColoredRect(canvas, border));
		}

		if (highlights.isEmpty())
		{
			return null;
		}

		Rectangle union = highlights.get(0).bounds;
		for (int i = 1; i < highlights.size(); i++)
		{
			union = union.union(highlights.get(i).bounds);
		}

		setPreferredLocation(new java.awt.Point(union.x, union.y));

		for (ColoredRect highlight : highlights)
		{
			Rectangle r = highlight.bounds;
			int x = r.x - union.x;
			int y = r.y - union.y;
			graphics.setColor(highlight.color);
			graphics.setStroke(new BasicStroke(2f));
			graphics.drawRoundRect(x, y, r.width, r.height, 6, 6);
		}

		return new Dimension(union.width, union.height);
	}

	private Color borderForSlot(int slot, GrandExchangeOffer offer, long stagnationSec)
	{
		if (offer.getState() != GrandExchangeOfferState.BUYING
			&& offer.getState() != GrandExchangeOfferState.SELLING)
		{
			return null;
		}

		boolean isBuy = offer.getState() == GrandExchangeOfferState.BUYING;
		int limitPrice = GeOfferPricing.limitPrice(offer);
		int unitFillPrice = GeOfferPricing.unitPrice(offer);
		FlipOpportunity opp = itemsClient.peekOpportunity(offer.getItemId());

		Color lockedLoss = lockedLossBorder(
			isBuy,
			limitPrice,
			unitFillPrice,
			offer.getItemId(),
			offer.getQuantitySold(),
			opp
		);
		if (lockedLoss != null)
		{
			return lockedLoss;
		}

		GeSlotTracker.SlotState tracked = slotTracker.snapshot().stream()
			.filter(s -> s.slot == slot)
			.findFirst()
			.orElse(null);
		long inactive = tracked != null ? tracked.inactiveSeconds() : 0;
		boolean stagnant = inactive >= stagnationSec;

		OfferPriceAnalyzer.Analysis analysis = OfferPriceAnalyzer.analyze(
			isBuy,
			limitPrice,
			opp,
			OfferPriceAnalyzer.DEFAULT_THRESHOLD_PERCENT,
			stagnant,
			inactive,
			offer.getQuantitySold(),
			offer.getTotalQuantity(),
			stagnationSec,
			unitFillPrice
		);

		if (analysis.action == OfferPriceAnalyzer.Action.ABORT_FLIP)
		{
			return PluginUi.NEGATIVE;
		}
		if (analysis.action == OfferPriceAnalyzer.Action.WAIT && analysis.issue != null)
		{
			return PluginUi.WARNING;
		}
		if (analysis.issue != null
			&& (analysis.action == OfferPriceAnalyzer.Action.REPRICE_BUY
			|| analysis.action == OfferPriceAnalyzer.Action.REPRICE_SELL))
		{
			return issueBorderColor(analysis.issue);
		}
		if (stagnant)
		{
			return PluginUi.WARNING.darker();
		}
		return null;
	}

	/**
	 * Red when the current offer price implies zero or negative net after GE tax
	 * (same economics as the copilot), even if the offer is within 1% of FlipX market.
	 */
	private static Color lockedLossBorder(
		boolean isBuy,
		long limitPrice,
		long unitFillPrice,
		int itemId,
		int quantityFilled,
		FlipOpportunity opp
	)
	{
		if (opp == null || limitPrice <= 0)
		{
			return null;
		}

		long netAtOffer;
		if (isBuy)
		{
			long buyForNet = GeOfferPricing.effectiveBuyForNet(
				limitPrice,
				opp.getEstimatedBuyPrice(),
				quantityFilled,
				unitFillPrice
			);
			long sellBasis = opp.getEstimatedSellPrice();
			if (sellBasis <= 0)
			{
				return null;
			}
			netAtOffer = OfferPriceAnalyzer.estimateNetPerItem(buyForNet, sellBasis, itemId);
		}
		else
		{
			long sellForNet = GeOfferPricing.effectiveSellForNet(
				limitPrice,
				opp.getEstimatedSellPrice(),
				quantityFilled,
				unitFillPrice
			);
			long buyBasis = opp.getEstimatedBuyPrice();
			if (buyBasis <= 0)
			{
				return null;
			}
			netAtOffer = OfferPriceAnalyzer.estimateNetPerItem(buyBasis, sellForNet, itemId);
			long breakEven = GeTax.breakEvenSellPrice(buyBasis, itemId);
			if (breakEven > 0 && limitPrice < breakEven)
			{
				return PluginUi.NEGATIVE;
			}
		}

		if (netAtOffer <= 0 && netAtOffer > Long.MIN_VALUE / 4)
		{
			return PluginUi.NEGATIVE;
		}
		return null;
	}

	private static Color issueBorderColor(OfferPriceAnalyzer.Issue issue)
	{
		switch (issue)
		{
			case BUY_OVERBID:
			case SELL_OVERCUT:
				return PluginUi.NEGATIVE;
			case BUY_UNDERBID:
			case SELL_UNDERCUT:
			default:
				return PluginUi.WARNING;
		}
	}

	private static final class ColoredRect
	{
		final Rectangle bounds;
		final Color color;

		ColoredRect(Rectangle bounds, Color color)
		{
			this.bounds = bounds;
			this.color = color;
		}
	}
}

package com.osrsflipfinder.runelite;

import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;

/** Portfolio time filters aligned with FlipX web ({@code portfolio-periods.ts}). */
enum PortfolioPeriod
{
	SESSION("session", "Current session"),
	DAY_1("1d", "Last 24 hours"),
	WEEK_1("1w", "Last 7 days"),
	MONTH_1("1m", "Last 30 days"),
	YEAR_1("1y", "Last 365 days"),
	ALL("all", "All time");

	static final PortfolioPeriod DEFAULT = SESSION;

	private static final PortfolioPeriod[] VALUES = values();
	static final String[] LABELS = buildLabels();

	private final String id;
	private final String label;

	PortfolioPeriod(String id, String label)
	{
		this.id = id;
		this.label = label;
	}

	String getId()
	{
		return id;
	}

	String getLabel()
	{
		return label;
	}

	boolean isLiveSession()
	{
		return this == SESSION;
	}

	String heroProfitTitle()
	{
		return isLiveSession() ? "Session P&L" : "Net profit";
	}

	String breakdownSectionTitle()
	{
		if (isLiveSession())
		{
			return "Session breakdown";
		}
		return label + " breakdown";
	}

	String topItemsSectionTitle()
	{
		if (isLiveSession())
		{
			return "Top items this session";
		}
		return "Top items · " + label.toLowerCase();
	}

	String heroTimeLabel()
	{
		return isLiveSession() ? "Session time" : "Flip time";
	}

	static PortfolioPeriod fromId(String raw)
	{
		if (raw == null || raw.isBlank())
		{
			return DEFAULT;
		}
		for (PortfolioPeriod period : VALUES)
		{
			if (period.id.equals(raw))
			{
				return period;
			}
		}
		return DEFAULT;
	}

	static int indexOf(PortfolioPeriod period)
	{
		for (int i = 0; i < VALUES.length; i++)
		{
			if (VALUES[i] == period)
			{
				return i;
			}
		}
		return 0;
	}

	static PortfolioPeriod fromIndex(int index)
	{
		if (index < 0 || index >= VALUES.length)
		{
			return DEFAULT;
		}
		return VALUES[index];
	}

	/** Query string for {@code /api/plugin/session} and analytics (without leading {@code ?}). */
	String toApiQuery()
	{
		StringBuilder q = new StringBuilder("account=all&period=").append(urlEncode(id));
		if (isLiveSession())
		{
			q.append("&days=30&liveSession=1");
			return q.toString();
		}

		java.time.Instant to = java.time.Instant.now();
		java.time.Instant from = null;
		int days = 30;
		if (this == DAY_1)
		{
			from = to.minus(java.time.Duration.ofDays(1));
			days = 1;
		}
		else if (this == WEEK_1)
		{
			from = to.minus(java.time.Duration.ofDays(7));
			days = 7;
		}
		else if (this == MONTH_1)
		{
			from = to.minus(java.time.Duration.ofDays(30));
			days = 30;
		}
		else if (this == YEAR_1)
		{
			from = to.minus(java.time.Duration.ofDays(365));
			days = 365;
		}

		if (this == ALL)
		{
			q.append("&days=3650");
		}
		else if (from != null)
		{
			q.append("&days=").append(days);
			q.append("&from=").append(urlEncode(from.toString()));
			q.append("&to=").append(urlEncode(to.toString()));
		}
		return q.toString();
	}

	String sessionCacheKey()
	{
		return "session-" + id;
	}

	String sessionItemsCacheKey()
	{
		return "session-items-" + id;
	}

	private static String[] buildLabels()
	{
		String[] labels = new String[VALUES.length];
		for (int i = 0; i < VALUES.length; i++)
		{
			labels[i] = VALUES[i].label;
		}
		return labels;
	}

	private static String urlEncode(String value)
	{
		try
		{
			return URLEncoder.encode(value, StandardCharsets.UTF_8.name());
		}
		catch (UnsupportedEncodingException ex)
		{
			return value;
		}
	}
}

