	void refreshUi()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (PairingCredentials.clearIfApiHostChanged(configManager, config))
			{
				onError("API URL changed - pair again in Connection (flipx.gg).");
			}
			PluginState state = resolveState();
			updateStatusBadge(state);
			updateConnectionLayout(state);
			updateMeta();
			updateTrialCountdown();
			headerUpgradeButton.setVisible(state == PluginState.UPGRADE_REQUIRED);
			PluginUi.setCardCaption(queueLabel, "Queue: " + ingestClient.getQueueSize() + " events");
			disconnectButton.setEnabled(PairingCredentials.isPaired(config));
			applySectionActiveStates();
			itemCatalogSearch.setEnabled(isPairedForMarket());
			marketPanel.refreshUi();
			if (isPairedForMarket())
			{
				opportunitiesClient.requestEntitlementsRefresh();
			}
			refreshSectionData(currentSection);
		});
	}

	private boolean isPairedForMarket()
	{
		return PairingCredentials.isPairedForCurrentApi(config);
	}

	private void updateConnectionLayout(PluginState state)
	{
		boolean paired = isPairedForMarket();
		pairingForm.setVisible(!paired);
		connectedSummary.setVisible(paired);
		if (!paired)
		{
			PluginUi.setCardCaption(pairingSuccessLabel, "");
		}
	}

	private void selectSection(SidebarSection section)
	{
		int index = section.ordinal();
		if (sectionCombo.getSelectedIndex() != index)
		{
			sectionCombo.setSelectedIndex(index);
		}
		else
		{
			showSection(section);
		}
	}

	private void connect()
	{
		if (!config.enableUpload() && !config.enableMarketPanel())
		{
			onError("Enable GE upload or the Market panel in plugin settings first");
			selectSection(SidebarSection.CONNECTION);
			return;
		}

		String code = new String(codeField.getPassword()).trim();
		if (code.length() != 6)
		{
			onError("Enter the 6-digit pairing code from the web app");
			selectSection(SidebarSection.CONNECTION);
			return;
		}

		connectButton.setEnabled(false);
		onStateChanged(PluginState.SYNCING);
		onError(null);

		executorService.execute(() ->
		{
			try
			{
				String deviceId = ensureDeviceId();

				PairingService.PairingResult result = pairingService.pair(
					code,
					deviceId,
					"RuneLite"
				);

				PairingCredentials.save(configManager, result.getApiKey());

				SwingUtilities.invokeLater(() ->
				{
					codeField.setText("");
					connectButton.setEnabled(true);
					disconnectButton.setEnabled(true);
					onError(null);
					PluginUi.setCardCaption(
						pairingSuccessLabel,
						"Paired. GE sync and 7-day portfolio are active on Free — upgrade for full history."
					);
					refreshUi();
					geEventListener.backfillAllSlots();
					selectSection(SidebarSection.MARKET);
				});
			}
			catch (Exception e)
			{
				log.warn("Pairing failed", e);
				SwingUtilities.invokeLater(() ->
				{
					connectButton.setEnabled(true);
					onStateChanged(PluginState.NOT_PAIRED);
					onError(e.getMessage());
					selectSection(SidebarSection.CONNECTION);
				});
			}
		});
	}

	private void disconnect()
	{
		String apiKey = config.apiKey();

		disconnectButton.setEnabled(false);
		connectButton.setEnabled(false);

		executorService.execute(() ->
		{
			if (apiKey != null && !apiKey.isBlank())
			{
				try
				{
					pairingService.revokeSelf(apiKey);
				}
				catch (IOException e)
				{
					log.warn("Remote revoke failed; clearing local credentials", e);
				}
			}

			SwingUtilities.invokeLater(() ->
			{
				PairingCredentials.clear(configManager);
				codeField.setText("");
				connectButton.setEnabled(true);
				disconnectButton.setEnabled(false);
				onError(null);
				refreshUi();
				selectSection(SidebarSection.CONNECTION);
			});
		});
	}

	private void openUrl(String path)
	{
		LinkBrowser.browse(FlipXConstants.baseUrl() + path);
	}

	private String ensureDeviceId()
	{
		String deviceId = config.deviceId();
		if (deviceId == null || deviceId.isBlank())
		{
			deviceId = UUID.randomUUID().toString();
			configManager.setConfiguration(FlipFinderConfig.GROUP, "deviceId", deviceId);
		}
		return deviceId;
	}

	private PluginState resolveState()
	{
		if (authFailureState == PluginState.REPAIR_REQUIRED && PairingCredentials.isPaired(config))
		{
			return PluginState.REPAIR_REQUIRED;
		}
		if (!PairingCredentials.isPairedForCurrentApi(config))
		{
			return PluginState.NOT_PAIRED;
		}
		if (authFailureState == PluginState.UPGRADE_REQUIRED)
		{
			return PluginState.UPGRADE_REQUIRED;
		}
		return PluginState.CONNECTED;
	}

	private void updateMeta()
	{
		String pairedAt = config.pairedAt();
		if (pairedAt == null || pairedAt.isBlank())
		{
			PluginUi.setCardCaption(metaLabel, "Not paired");
			return;
		}
		PluginUi.setCardCaption(
			metaLabel,
			"Paired " + pairedAt.replace('T', ' ').substring(0, Math.min(19, pairedAt.length()))
				+ tierSuffix()
		);
	}

	private String tierSuffix()
	{
		PluginEntitlements entitlements = opportunitiesClient.getEntitlements();
		if (entitlements == null)
		{
			return "";
		}
		if (entitlements.isTrialing())
		{
			Integer days = entitlements.getTrialDaysRemaining();
			if (days != null && days > 0)
			{
				return " · Pro trial (" + days + "d left)";
			}
			return " · Pro trial";
		}
		if (entitlements.hasProAccess())
		{
			return " · Pro";
		}
		return " · Free (sync + 7-day history)";
	}

	private void updateTrialCountdown()
	{
		PluginEntitlements entitlements = opportunitiesClient.getEntitlements();
		if (entitlements == null || !entitlements.isTrialing())
		{
			PluginUi.setCardCaption(trialCountdownLabel, "");
			return;
		}
		Integer days = entitlements.getTrialDaysRemaining();
		if (days != null && days > 0)
		{
			PluginUi.setCardCaption(
				trialCountdownLabel,
				"Pro trial: " + days + " day" + (days == 1 ? "" : "s") + " left — full history unlocked"
			);
			return;
		}
		PluginUi.setCardCaption(trialCountdownLabel, "Pro trial active — full history unlocked");
	}

	private void onSyncStats(IngestClient.SyncStats stats)
	{
		SwingUtilities.invokeLater(() ->
		{
			PluginUi.setCardCaption(
				lastSyncLabel,
				String.format(
					"Last sync %s | +%d | skipped %d",
					TIME_FORMAT.format(stats.getSyncedAt()),
					stats.getInserted(),
					stats.getSkipped()
				)
			);
			PluginUi.setCardCaption(queueLabel, "Queue: " + ingestClient.getQueueSize() + " events");
		});
	}

	private void onStateChanged(PluginState state)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (state == PluginState.REPAIR_REQUIRED || state == PluginState.UPGRADE_REQUIRED)
			{
				authFailureState = state;
			}
			else if (state == PluginState.CONNECTED)
			{
				authFailureState = null;
			}

			if (state == PluginState.REPAIR_REQUIRED || state == PluginState.NOT_PAIRED)
			{
				refreshUi();
				if (state == PluginState.REPAIR_REQUIRED)
				{
					onError("Invalid API key - pair again in Connection.");
				}
				if (currentSection != SidebarSection.CONNECTION)
				{
					selectSection(SidebarSection.CONNECTION);
				}
				return;
			}

			// Avoid re-fetching market on every successful poll (refreshUi -> requestMarketRefresh loop).
			updateStatusBadge(resolveState());
			queueLabel.setText("Queue: " + ingestClient.getQueueSize() + " events");
			disconnectButton.setEnabled(PairingCredentials.isPaired(config));
			applySectionActiveStates();
		});
	}

	private void onError(String message)
	{
		SwingUtilities.invokeLater(() ->
		{
			PluginUi.setSidebarError(errorLabel, message);
			connectionViewPanel.revalidate();
			connectionViewPanel.repaint();
		});
	}

	private void updateStatusBadge(PluginState state)
	{
		JLabel fresh = PluginUi.statusBadge(state);
		statusBadge.setText(fresh.getText());
		statusBadge.setForeground(fresh.getForeground());
		statusBadge.setBorder(fresh.getBorder());
	}
}

package com.osrsflipfinder.runelite;

/** Formats countdown text aligned with {@code formatNextRefreshInlineLabel} on web. */
final class RefreshCountdown
{
	private RefreshCountdown()
	{
	}

	static String formatPolling(
		long nextRefreshAtMs,
		boolean pollingActive,
		boolean fetchInProgress
	)
	{
		if (!pollingActive)
		{
			return "Refresh paused (switch to this tab to resume)";
		}
		if (fetchInProgress)
		{
			return "Refreshing…";
		}
		if (nextRefreshAtMs <= 0)
		{
			return "Next refresh in 0s";
		}
		long remainingMs = ClientSchedule.msUntilNextFetch(
			nextRefreshAtMs,
			System.currentTimeMillis()
		);
		long sec = formatNextRefreshCountdownSeconds(remainingMs);
		return String.format("Next refresh in %ds", sec);
	}

	/** Matches {@code formatNextRefreshCountdownSeconds} in client-schedule.ts. */
	static long formatNextRefreshCountdownSeconds(long remainingMs)
	{
		return Math.max(0, (remainingMs + 999) / 1000);
	}

	static String combine(String primary, String secondary)
	{
		boolean hasPrimary = primary != null && !primary.isBlank();
		boolean hasSecondary = secondary != null && !secondary.isBlank();
		if (hasPrimary && hasSecondary)
		{
			return primary + " | " + secondary;
		}
		if (hasPrimary)
		{
			return primary;
		}
		if (hasSecondary)
		{
			return secondary;
		}
		return " ";
	}
}

package com.osrsflipfinder.runelite;

import com.google.gson.Gson;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Persists last-known API payloads under {@code ~/.runelite/flipx/} for offline
 * display when network requests fail.
 */
@Slf4j
@Singleton
public class LocalCacheStore
{
	static final long DEFAULT_MAX_AGE_MS = 24L * 60L * 60L * 1000L;

	private final Gson gson;
	private final Path cacheDir;

	@Inject
	LocalCacheStore(Gson gson)
	{
		this.gson = gson;
		this.cacheDir = RuneLite.RUNELITE_DIR.toPath().resolve("flipx");
	}

	boolean isEnabled(FlipFinderConfig config)
	{
		return config.enableOfflineCache();
	}

	<T> void write(String key, T payload, FlipFinderConfig config)
	{
		if (!isEnabled(config) || payload == null)
		{
			return;
		}
		try
		{
			Files.createDirectories(cacheDir);
			Envelope<T> envelope = new Envelope<>(payload, Instant.now().toString());
			Path target = cacheDir.resolve(safeKey(key) + ".json");
			Files.writeString(target, gson.toJson(envelope), StandardCharsets.UTF_8);
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Failed to write cache entry {}", key, ex);
		}
	}

	<T> CachedEntry<T> read(String key, Class<T> type, FlipFinderConfig config)
	{
		if (!isEnabled(config))
		{
			return null;
		}
		try
		{
			Path target = cacheDir.resolve(safeKey(key) + ".json");
			if (!Files.isRegularFile(target))
			{
				return null;
			}
			String raw = Files.readString(target, StandardCharsets.UTF_8);
			Envelope<T> envelope = gson.fromJson(raw, Envelope.type(type));
			if (envelope == null || envelope.payload == null || envelope.cachedAt == null)
			{
				return null;
			}
			Instant cachedAt = Instant.parse(envelope.cachedAt);
			if (Instant.now().toEpochMilli() - cachedAt.toEpochMilli() > DEFAULT_MAX_AGE_MS)
			{
				return null;
			}
			return new CachedEntry<>(envelope.payload, cachedAt);
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Failed to read cache entry {}", key, ex);
			return null;
		}
	}

	static String formatCachedAt(Instant cachedAt)
	{
		if (cachedAt == null)
		{
			return "unknown time";
		}
		return cachedAt.toString().replace('T', ' ').substring(0, Math.min(16, cachedAt.toString().length()));
	}

	private static String safeKey(String key)
	{
		return key.replaceAll("[^a-zA-Z0-9._-]", "_");
	}

	static final class CachedEntry<T>
	{
		private final T payload;
		private final Instant cachedAt;

		CachedEntry(T payload, Instant cachedAt)
		{
			this.payload = payload;
			this.cachedAt = cachedAt;
		}

		T getPayload()
		{
			return payload;
		}

		Instant getCachedAt()
		{
			return cachedAt;
		}
	}

	private static final class Envelope<T>
	{
		private T payload;
		private String cachedAt;

		Envelope(T payload, String cachedAt)
		{
			this.payload = payload;
			this.cachedAt = cachedAt;
		}

		static <T> java.lang.reflect.Type type(Class<T> clazz)
		{
			return com.google.gson.reflect.TypeToken.getParameterized(Envelope.class, clazz).getType();
		}
	}
}

package com.osrsflipfinder.runelite;

import java.util.HashMap;
import java.util.Map;

/** Reduces flip-manager UI flicker from threshold edge cases and brief null market data. */
final class SlotAnalysisStabilizer
{
	private static final long STAGNANT_ENTER_BUFFER_SEC = 45L;
	private static final long STAGNANT_EXIT_BUFFER_SEC = 20L;
	private static final double ISSUE_CLEAR_FACTOR = 0.5;

	private final Map<Integer, Boolean> stagnantLatched = new HashMap<>();
	private final Map<Integer, OfferPriceAnalyzer.Issue> issueLatched = new HashMap<>();
	private final Map<Integer, OfferPriceAnalyzer.Analysis> alertFallback = new HashMap<>();
	private final Map<Integer, OfferPriceAnalyzer.Analysis> holdFallback = new HashMap<>();

	void clearSlot(int slot)
	{
		stagnantLatched.remove(slot);
		issueLatched.remove(slot);
		alertFallback.remove(slot);
		holdFallback.remove(slot);
	}

	boolean stagnantForUi(int slot, long inactiveSec, long thresholdSec, boolean rawStagnant)
	{
		if (!rawStagnant)
		{
			stagnantLatched.remove(slot);
			return false;
		}
		if (Boolean.TRUE.equals(stagnantLatched.get(slot)))
		{
			if (inactiveSec < Math.max(0, thresholdSec - STAGNANT_EXIT_BUFFER_SEC))
			{
				stagnantLatched.remove(slot);
				return false;
			}
		 return true;
		}
		if (inactiveSec >= thresholdSec + STAGNANT_ENTER_BUFFER_SEC)
		{
			stagnantLatched.put(slot, true);
			return true;
		}
		return false;
	}

	OfferPriceAnalyzer.Analysis stabilize(int slot, OfferPriceAnalyzer.Analysis fresh)
	{
		if (fresh == null)
		{
			return null;
		}

		if (fresh.issue != null)
		{
			issueLatched.put(slot, fresh.issue);
			alertFallback.put(slot, fresh);
			return fresh;
		}

		if (fresh.action == OfferPriceAnalyzer.Action.ABORT_FLIP
			|| fresh.action == OfferPriceAnalyzer.Action.REPRICE_BUY
			|| fresh.action == OfferPriceAnalyzer.Action.REPRICE_SELL)
		{
			issueLatched.remove(slot);
			alertFallback.remove(slot);
			holdFallback.put(slot, fresh);
			return fresh;
		}

		if (fresh.action == OfferPriceAnalyzer.Action.WAIT)
		{
			alertFallback.put(slot, fresh);
			return fresh;
		}

		OfferPriceAnalyzer.Issue latchedIssue = issueLatched.get(slot);
		if (latchedIssue != null && fresh.deltaPercent != null)
		{
			if (Math.abs(fresh.deltaPercent) > OfferPriceAnalyzer.DEFAULT_THRESHOLD_PERCENT * ISSUE_CLEAR_FACTOR)
			{
				OfferPriceAnalyzer.Analysis prev = alertFallback.get(slot);
				if (prev != null)
				{
					return prev;
				}
			}
			else
			{
				issueLatched.remove(slot);
				alertFallback.remove(slot);
			}
		}

		if (fresh.action == OfferPriceAnalyzer.Action.HOLD)
		{
			if (fresh.marketPrice == null || fresh.marketPrice <= 0)
			{
				OfferPriceAnalyzer.Analysis prev = holdFallback.get(slot);
				if (prev != null && prev.marketPrice != null && prev.marketPrice > 0)
				{
					return prev;
				}
			}
			else
			{
				holdFallback.put(slot, fresh);
			}
		}

		return fresh;
	}
}

