/**
 * FlipX icons on the GE setup panel: buy-limit on the quantity row (buy only) and
 * suggested price on the Guide price slot (buy and sell). Clicking an icon prefills
 * the native Enter quantity / Enter price chatbox if that dialog is already open,
 * or remembers the value until you open it. You still press Enter and Confirm.
 */
@Slf4j
@Singleton
class GeFlipxSetupAssist
{
	private static final int GE_OFFERS_GROUP = 465;
	/** Clientscript wrapper; {@link ScriptID#GE_OFFERS_SETUP_BUILD} is the proc it calls. */
	private static final int GE_OFFERS_SETUP_DRAW_CLIENTSCRIPT = 776;
	/** Fired when GE price/count meslayer chat opens after Enter price. */
	private static final int CS_MESLAYER_CHAT_OPEN = 108;
	private static final int GE_BTN = 35;
	private static final int ICON_W = 14;
	private static final int ICON_H = 12;
	private static final int FLIPX_GE_BUTTON_SPRITE = 0x7f1_0001;

	private final Client client;
	private final ClientThread clientThread;
	private final FlipFinderConfig config;
	private final ItemManager itemManager;
	private final ItemsClient itemsClient;
	private final BuyLimitClient buyLimitClient;
	private final OpportunitiesClient opportunitiesClient;
	private final CoinBalanceService coinBalanceService;
	private final ScheduledExecutorService executorService;

	private Widget quantityButton;
	private Widget quantityLabel;
	private Widget priceButton;
	private Widget priceLabel;
	private volatile int pendingBuyLimitItemId = -1;
	private volatile int lastSetupItemId = -1;
	private volatile int pendingPriceItemId = -1;
	private volatile int pendingChatValue = -1;
	private volatile GeOfferChatInput.Step pendingChatStep = GeOfferChatInput.Step.NONE;

	@Inject
	GeFlipxSetupAssist(
		Client client,
		ClientThread clientThread,
		FlipFinderConfig config,
		ItemManager itemManager,
		ItemsClient itemsClient,
		BuyLimitClient buyLimitClient,
		OpportunitiesClient opportunitiesClient,
		CoinBalanceService coinBalanceService,
		ScheduledExecutorService executorService
	)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.itemManager = itemManager;
		this.itemsClient = itemsClient;
		this.buyLimitClient = buyLimitClient;
		this.opportunitiesClient = opportunitiesClient;
		this.coinBalanceService = coinBalanceService;
		this.executorService = executorService;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!FlipFinderConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		clientThread.invokeLater(() ->
		{
			if (!isFeatureEnabled())
			{
				hideButtons();
				clearAppliedOfferState();
				return;
			}
			scheduleAttachButtons();
		});
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (isSetupDrawScript(event.getScriptId()))
		{
			scheduleAttachButtons();
			return;
		}
		if (event.getScriptId() == CS_MESLAYER_CHAT_OPEN && pendingChatValue > 0)
		{
			clientThread.invokeLater(this::tryFinishPendingChatPrefill);
		}
	}

	private static boolean isSetupDrawScript(int scriptId)
	{
		return scriptId == ScriptID.GE_OFFERS_SETUP_BUILD
			|| scriptId == GE_OFFERS_SETUP_DRAW_CLIENTSCRIPT;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == GE_OFFERS_GROUP)
		{
			scheduleAttachButtons();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!isFeatureEnabled())
		{
			hideButtons();
			clearAppliedOfferState();
			return;
		}
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isSelfHidden())
		{
			hideButtons();
			clearAppliedOfferState();
			return;
		}
		int itemId = GeItemResolver.resolve(client);
		if (itemId > 0 && itemId != lastSetupItemId)
		{
			clearPendingChat();
			scheduleAttachButtons();
			return;
		}
		if (!hasLiveButtons(setup))
		{
			scheduleAttachButtons();
		}
		tryFinishPendingChatPrefill();
	}

	private boolean hasLiveButtons(Widget setup)
	{
		boolean buyOffer = isBuyOfferSetup();
		boolean priceLive = isLiveButton(priceButton, setup);
		if (!priceLive)
		{
			return false;
		}
		if (buyOffer)
		{
			return isLiveButton(quantityButton, setup);
		}
		return true;
	}

	private void scheduleAttachButtons()
	{
		if (!isFeatureEnabled())
		{
			clientThread.invokeLater(this::hideButtons);
			return;
		}
		clientThread.invokeLater(this::attachButtons);
	}

	private void attachButtons()
	{
		if (!isFeatureEnabled())
		{
			hideButtons();
			return;
		}

		int itemId = GeItemResolver.resolve(client);
		if (itemId <= 0)
		{
			hideButtons();
			return;
		}
		lastSetupItemId = itemId;

		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isSelfHidden())
		{
			hideButtons();
			return;
		}

		prefetchSetupAssistData(itemId);

		if (!ensureFlipxSprite())
		{
			return;
		}

		boolean buyOffer = isBuyOfferSetup();
		if (!buyOffer && isLiveButton(quantityButton, setup))
		{
			hideWidget(quantityButton);
			hideWidget(quantityLabel);
			quantityButton = null;
			quantityLabel = null;
		}

		if (buyOffer)
		{
			Widget qtyAnchor = findQuantityPluginAnchor(setup);
			if (qtyAnchor != null)
			{
				stealNativeSlot(qtyAnchor);
				hidePlus1kLabel(setup, qtyAnchor);
				quantityButton = ensureIconButton(
					setup,
					quantityButton,
					qtyAnchor,
					true,
					"FlipX buy limit",
					() -> onBuyLimitClicked(itemId)
				);
				quantityLabel = ensureIconLabel(setup, quantityLabel, true);
			}
			else
			{
				quantityButton = null;
			}
		}

		Widget priceAnchor = findGuidePriceAnchor(setup);
		if (priceAnchor != null)
		{
			String action = buyOffer ? "FlipX buy price" : "FlipX sell price";
			priceButton = ensureIconButton(
				setup,
				priceButton,
				priceAnchor,
				false,
				action,
				() -> onFlipxPriceClicked(itemId, buyOffer)
			);
			priceLabel = ensureIconLabel(setup, priceLabel, false);
		}
		else
		{
			priceButton = null;
		}
	}

	private void prefetchSetupAssistData(int itemId)
	{
		executorService.execute(() ->
		{
			try
			{
				if (itemsClient.peek(itemId) == null || itemsClient.isStale(itemId))
				{
					itemsClient.fetch(itemId);
				}
			}
			catch (Exception e)
			{
				log.debug("FlipX setup prefetch item detail failed", e);
			}
		});

		long accountHash = client.getAccountHash();
		if (accountHash == -1)
		{
			return;
		}
		String account = String.valueOf(accountHash);
		if (buyLimitClient.peek(account, itemId) != null)
		{
			return;
		}
		executorService.execute(() ->
		{
			try
			{
				buyLimitClient.fetch(account, itemId);
			}
			catch (Exception e)
			{
				log.debug("FlipX setup prefetch buy limit failed", e);
			}
		});
	}

	private Widget ensureIconButton(
		Widget setup,
		Widget existing,
		Widget anchor,
		boolean quantitySlot,
		String action,
		Runnable onClick
	)
	{
		if (isLiveButton(existing, setup))
		{
			applyNativeButtonBounds(existing, setup, anchor, quantitySlot);
			bindButton(existing, action, onClick);
			existing.setHidden(false);
			existing.revalidate();
			return existing;
		}
		return attachIconButton(setup, anchor, quantitySlot, action, onClick);
	}

	private Widget attachIconButton(
		Widget setup,
		Widget anchor,
		boolean quantitySlot,
		String action,
		Runnable onClick
	)
	{
		Widget btn = setup.createChild(-1, WidgetType.GRAPHIC);
		Widget peer = findSizePeer(setup, quantitySlot);
		int spriteId = peer != null ? peer.getSpriteId() : -1;
		btn.setSpriteId(spriteId > 0 ? spriteId : FLIPX_GE_BUTTON_SPRITE);
		btn.setHasListener(true);
		btn.setNoClickThrough(true);
		applyNativeButtonBounds(btn, setup, anchor, quantitySlot);
		bindButton(btn, action, onClick);
		btn.revalidate();
		return btn;
	}

	private Widget ensureIconLabel(Widget setup, Widget existing, boolean quantitySlot)
	{
		ButtonMetrics metrics = nativeButtonMetrics(
			setup,
			quantitySlot ? findQuantityPluginAnchor(setup) : findGuidePriceAnchor(setup),
			quantitySlot
		);
		if (metrics == null)
		{
			return existing;
		}
		Widget label = existing;
		if (!isLiveButton(label, setup))
		{
			label = setup.createChild(-1, WidgetType.TEXT);
		}
		Widget style = findPeerLabel(setup, quantitySlot);
		label.setText("X");
		label.setHidden(false);
		label.setNoClickThrough(false);
		label.setHasListener(false);
		if (style != null)
		{
			label.setFontId(style.getFontId());
			label.setTextColor(style.getTextColor());
			label.setXTextAlignment(style.getXTextAlignment());
			label.setYTextAlignment(style.getYTextAlignment());
		}
		label.setWidthMode(WidgetSizeMode.ABSOLUTE);
		label.setHeightMode(WidgetSizeMode.ABSOLUTE);
		label.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		label.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		label.setOriginalX(metrics.x);
		label.setOriginalY(metrics.y);
		label.setOriginalWidth(metrics.w);
		label.setOriginalHeight(metrics.h);
		label.revalidate();
		return label;
	}

	private void bindButton(Widget btn, String action, Runnable onClick)
	{
		btn.setAction(0, action);
		btn.setOnOpListener((JavaScriptCallback) ev ->
			clientThread.invoke(onClick)
		);
	}

	private static void applyNativeButtonBounds(
		Widget btn,
		Widget setup,
		Widget slot,
		boolean quantitySlot
	)
	{
		ButtonMetrics metrics = nativeButtonMetrics(setup, slot, quantitySlot);
		if (metrics == null)
		{
			return;
		}
		btn.setWidthMode(WidgetSizeMode.ABSOLUTE);
		btn.setHeightMode(WidgetSizeMode.ABSOLUTE);
		btn.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		btn.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		btn.setOriginalWidth(metrics.w);
		btn.setOriginalHeight(metrics.h);
		btn.setOriginalX(metrics.x);
		btn.setOriginalY(metrics.y);
	}

	static ButtonMetrics nativeButtonMetrics(Widget setup, Widget slot, boolean quantitySlot)
	{
		if (slot == null)
		{
			return null;
		}
		Widget sizePeer = findSizePeer(setup, quantitySlot);
		int w = firstPositive(
			sizePeer != null ? sizePeer.getWidth() : 0,
			sizePeer != null ? sizePeer.getOriginalWidth() : 0,
			slot.getWidth(),
			slot.getOriginalWidth(),
			GE_BTN
		);
		int h = firstPositive(
			sizePeer != null ? sizePeer.getHeight() : 0,
			sizePeer != null ? sizePeer.getOriginalHeight() : 0,
			slot.getHeight(),
			slot.getOriginalHeight(),
			GE_BTN
		);
		int slotW = firstPositive(slot.getWidth(), slot.getOriginalWidth(), w);
		int x = slot.getOriginalX();
		int y = sizePeer != null ? sizePeer.getOriginalY() : slot.getOriginalY();
		if (slotW > w)
		{
			x += (slotW - w) / 2;
		}
		return new ButtonMetrics(x, y, w, h);
	}

	static Widget findSizePeer(Widget setup, boolean quantitySlot)
	{
		String[] peers = quantitySlot
			? new String[] { "+100", "+10", "+1" }
			: new String[] { "-5%", "+5%", "-99%", "+99%" };
		for (String action : peers)
		{
			Widget peer = GeSetupWidgetSearch.findByAction(setup, action);
			if (peer != null && firstPositive(peer.getWidth(), peer.getOriginalWidth(), 0) > 0)
			{
				return peer;
			}
		}
		return null;
	}

	static Widget findPeerLabel(Widget setup, boolean quantitySlot)
	{
		if (setup == null)
		{
			return null;
		}
		String[] texts = quantitySlot
			? new String[] { "+100", "+10", "+1" }
			: new String[] { "-5%", "+5%", "-99%", "+99%" };
		Widget[] children = setup.getDynamicChildren();
		if (children == null)
		{
			return null;
		}
		for (String text : texts)
		{
			for (Widget child : children)
			{
				if (child != null
					&& child.getType() == WidgetType.TEXT
					&& text.equals(child.getText()))
				{
					return child;
				}
			}
		}
		return null;
	}

	static int firstPositive(int... values)
	{
		for (int value : values)
		{
			if (value > 0)
			{
				return value;
			}
		}
		return GE_BTN;
	}

	/**
	 * Take over a native GE slot (+1K / Guide price) so leftover clicks cannot
	 * fire the original op (notably +1K → quantity 1000).
	 */
	static void stealNativeSlot(Widget nativeBtn)
	{
		if (nativeBtn == null)
		{
			return;
		}
		nativeBtn.setHasListener(false);
		String[] actions = nativeBtn.getActions();
		if (actions != null)
		{
			for (int i = 0; i < actions.length; i++)
			{
				nativeBtn.setAction(i, null);
			}
		}
		nativeBtn.setHidden(true);
	}

	static boolean isLiveButton(Widget button, Widget setup)
	{
		if (button == null || setup == null)
		{
			return false;
		}
		try
		{
			return !button.isHidden() && button.getParent() == setup;
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	static Widget findQuantityPluginAnchor(Widget setup)
	{
		if (setup == null)
		{
			return null;
		}

		Widget[] children = setup.getDynamicChildren();
		if (children == null)
		{
			return null;
		}

		for (Widget text : children)
		{
			if (text == null || text.getType() != WidgetType.TEXT)
			{
				continue;
			}
			if (!"+1K".equals(text.getText()))
			{
				continue;
			}
			int tx = text.getOriginalX();
			int ty = text.getOriginalY();
			for (Widget graphic : children)
			{
				if (graphic == null || graphic.getType() != WidgetType.GRAPHIC)
				{
					continue;
				}
				if (graphic.getOriginalX() == tx && graphic.getOriginalY() == ty)
				{
					return graphic;
				}
			}
		}

		return null;
	}

	static Widget findGuidePriceAnchor(Widget setup)
	{
		if (setup == null)
		{
			return null;
		}
		Widget[] children = setup.getDynamicChildren();
		if (children == null)
		{
			return null;
		}
		for (Widget w : children)
		{
			if (w == null || w.getType() != WidgetType.GRAPHIC)
			{
				continue;
			}
			String[] actions = w.getActions();
			if (actions == null)
			{
				continue;
			}
			for (String action : actions)
			{
				if ("Guide price".equals(action))
				{
					return w;
				}
			}
		}
		return null;
	}

	private static void hidePlus1kLabel(Widget setup, Widget anchor)
	{
		Widget[] children = setup.getDynamicChildren();
		if (children == null)
		{
			return;
		}
		int ax = anchor.getOriginalX();
		int ay = anchor.getOriginalY();
		for (Widget text : children)
		{
			if (text != null
				&& text.getType() == WidgetType.TEXT
				&& "+1K".equals(text.getText())
				&& text.getOriginalX() == ax
				&& text.getOriginalY() == ay)
			{
				text.setHidden(true);
			}
		}
	}

	private void onBuyLimitClicked(int itemId)
	{
		if (!isCurrentSetupItem(itemId))
		{
			return;
		}
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		int clientBought = GeOfferSetupBuyProgress.parseBoughtSoFar(setup);

		long accountHash = client.getAccountHash();
		if (accountHash == -1)
		{
			applyBuyLimitQuantity(itemId, null, clientBought);
			return;
		}
		String account = String.valueOf(accountHash);

		BuyLimitRemaining cached = buyLimitClient.peek(account, itemId);
		if (cached == null)
		{
			pendingBuyLimitItemId = itemId;
			if (clientBought >= 0)
			{
				applyBuyLimitQuantity(itemId, null, clientBought);
			}
			executorService.execute(() ->
			{
				try
				{
					buyLimitClient.fetch(account, itemId);
				}
				catch (Exception e)
				{
					log.debug("FlipX setup buy limit fetch failed", e);
				}
				clientThread.invokeLater(() ->
				{
					if (itemId != pendingBuyLimitItemId || !isCurrentSetupItem(itemId))
					{
						return;
					}
					pendingBuyLimitItemId = -1;
					Widget liveSetup = client.getWidget(InterfaceID.GeOffers.SETUP);
					int bought = GeOfferSetupBuyProgress.parseBoughtSoFar(liveSetup);
					BuyLimitRemaining fresh = buyLimitClient.peek(account, itemId);
					applyBuyLimitQuantity(itemId, fresh, bought);
				});
			});
			return;
		}

		applyBuyLimitQuantity(itemId, cached, clientBought);
	}

	private void applyBuyLimitQuantity(int itemId, BuyLimitRemaining synced, int clientBoughtSoFar)
	{
		if (!isCurrentSetupItem(itemId))
		{
			return;
		}
		ItemStats stats = itemManager.getItemStats(itemId);
		coinBalanceService.refresh();
		int offerPriceGp = GeOfferSetupScripts.readOfferPriceGp(client);
		long inventoryCoins = coinBalanceService.getCoins();
		int qty = GeFlipxBuyLimit.quantityToApply(
			synced,
			itemId,
			stats,
			clientBoughtSoFar,
			offerPriceGp,
			inventoryCoins
		);
		if (qty <= 0)
		{
			log.debug("FlipX buy-limit qty is 0 for item {}", itemId);
			return;
		}
		offerQuantity(qty);
	}

	private void onFlipxPriceClicked(int itemId, boolean buyOffer)
	{
		if (!isCurrentSetupItem(itemId))
		{
			return;
		}
		ItemDetailResponse detail = itemsClient.peek(itemId);
		boolean missing = detail == null || detail.getOpportunity() == null;
		if (!missing)
		{
			applyFlipxPrice(itemId, buyOffer);
		}
		if (missing || itemsClient.isStale(itemId))
		{
			final boolean applyAfterFetch = missing;
			pendingPriceItemId = itemId;
			executorService.execute(() ->
			{
				try
				{
					itemsClient.fetch(itemId);
				}
				catch (Exception e)
				{
					log.debug("FlipX setup price fetch failed", e);
				}
				if (!applyAfterFetch)
				{
					if (itemId == pendingPriceItemId)
					{
						pendingPriceItemId = -1;
					}
					return;
				}
				clientThread.invokeLater(() ->
				{
					if (itemId != pendingPriceItemId || !isCurrentSetupItem(itemId))
					{
						return;
					}
					pendingPriceItemId = -1;
					applyFlipxPrice(itemId, buyOffer);
				});
			});
		}
	}

	private void applyFlipxPrice(int itemId, boolean buyOffer)
	{
		if (!isCurrentSetupItem(itemId))
		{
			return;
		}
		ItemDetailResponse detail = itemsClient.peek(itemId);
		if (detail == null || detail.getOpportunity() == null)
		{
			return;
		}
		GeAssistPricing.ResolvedPrice resolved = GeAssistPricing.resolve(
			detail,
			buyOffer,
			opportunitiesClient.getEntitlements()
		);
		if (resolved == null || resolved.priceGp <= 0)
		{
			return;
		}
		long price = Math.min(
			GeAssistPricing.geOfferPriceGp(resolved, buyOffer, detail.getOpportunity()),
			Integer.MAX_VALUE
		);
		offerPrice((int) price);
	}

	private void offerQuantity(int quantity)
	{
		offerChatValue(quantity, GeOfferChatInput.Step.QUANTITY_BUY);
	}

	private void offerPrice(int priceGp)
	{
		offerChatValue(priceGp, GeOfferChatInput.Step.PRICE);
	}

	private void offerChatValue(int value, GeOfferChatInput.Step step)
	{
		if (value <= 0)
		{
			return;
		}
		Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (setup == null || setup.isSelfHidden())
		{
			return;
		}
		if (GeOfferChatInput.isOtherInputOpen(client))
		{
			return;
		}

		boolean wantPrice = step == GeOfferChatInput.Step.PRICE;
		if (wantPrice ? GeOfferChatInput.isQuantityOpen(client) : GeOfferChatInput.isPriceOpen(client))
		{
			return;
		}
		if (GeOfferChatInput.prefillIfStep(client, value, step))
		{
			clearPendingChat();
			return;
		}

		pendingChatValue = value;
		pendingChatStep = step;
	}

	private void tryFinishPendingChatPrefill()
	{
		if (pendingChatValue <= 0 || pendingChatStep == GeOfferChatInput.Step.NONE)
		{
			return;
		}
		if (GeOfferChatInput.prefillIfStep(client, pendingChatValue, pendingChatStep))
		{
			clearPendingChat();
		}
	}

	private boolean isCurrentSetupItem(int itemId)
	{
		return itemId > 0 && itemId == GeItemResolver.resolve(client);
	}

	private void clearPendingChat()
	{
		pendingChatValue = -1;
		pendingChatStep = GeOfferChatInput.Step.NONE;
	}

	private void clearAppliedOfferState()
	{
		clearPendingChat();
		lastSetupItemId = -1;
		pendingBuyLimitItemId = -1;
		pendingPriceItemId = -1;
	}

	private boolean isBuyOfferSetup()
	{
		return client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE) != 1
			&& client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH) > 0;
	}

	private boolean isFeatureEnabled()
	{
		return config.enableGePriceAssist()
			&& config.apiKey() != null
			&& !config.apiKey().isBlank();
	}

	private boolean ensureFlipxSprite()
	{
		Map<Integer, net.runelite.api.SpritePixels> overrides = client.getSpriteOverrides();
		if (overrides.containsKey(FLIPX_GE_BUTTON_SPRITE))
		{
			return true;
		}
		try
		{
			BufferedImage raw = ImageUtil.loadImageResource(OsrsFlipFinderPlugin.class, "icon.png");
			BufferedImage scaled = ImageUtil.resizeImage(raw, ICON_W, ICON_H);
			overrides.put(FLIPX_GE_BUTTON_SPRITE, ImageUtil.getImageSpritePixels(scaled, client));
			return true;
		}
		catch (RuntimeException e)
		{
			log.debug("FlipX setup sprite failed", e);
			return false;
		}
	}

	private void hideButtons()
	{
		hideWidget(quantityButton);
		hideWidget(quantityLabel);
		hideWidget(priceButton);
		hideWidget(priceLabel);
		quantityButton = null;
		quantityLabel = null;
		priceButton = null;
		priceLabel = null;
	}

	private static void hideWidget(Widget widget)
	{
		if (widget == null)
		{
			return;
		}
		try
		{
			widget.setHidden(true);
		}
		catch (RuntimeException ignored)
		{
		}
	}

	static final class ButtonMetrics
	{
		final int x;
		final int y;
		final int w;
		final int h;

		ButtonMetrics(int x, int y, int w, int h)
		{
			this.x = x;
			this.y = y;
			this.w = w;
			this.h = h;
		}
	}
}

package com.osrsflipfinder.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

/**
 * RuneLite's built-in Grand Exchange plugin stores completed trades per RS profile
 * in {@code grandexchange.tradeHistory}. We ingest missing rows after login to
 * recover flips that never uploaded during auth outages.
 */
@Slf4j
@Singleton
public class GeTradeHistoryBackfill
{
	private static final String RL_GE_GROUP = "grandexchange";
	private static final String RL_TRADE_HISTORY = "tradeHistory";
	private static final String WATERMARK_CONFIG_KEY = "geTradeHistoryWatermark";
	private static final long WATERMARK_OVERLAP_MINUTES = 10L;

	private static final Type TRADE_LIST_TYPE = new TypeToken<List<RuneliteHistoryTrade>>()
	{
	}.getType();

	private final Client client;
	private final ConfigManager configManager;
	private final FlipFinderConfig config;
	private final Gson gson;
	private final IngestClient ingestClient;
	private final ItemManager itemManager;

	@Inject
	GeTradeHistoryBackfill(
		Client client,
		ConfigManager configManager,
		FlipFinderConfig config,
		Gson gson,
		IngestClient ingestClient,
		ItemManager itemManager
	)
	{
		this.client = client;
		this.configManager = configManager;
		this.config = config;
		this.gson = gson;
		this.ingestClient = ingestClient;
		this.itemManager = itemManager;
	}

	void syncFromRuneliteProfileHistory()
	{
		if (!ingestClient.isConfigured())
		{
			return;
		}

		long accountHash = client.getAccountHash();
		if (accountHash == -1)
		{
			return;
		}

		String raw = configManager.getRSProfileConfiguration(RL_GE_GROUP, RL_TRADE_HISTORY);
		if (raw == null || raw.isBlank())
		{
			return;
		}

		List<RuneliteHistoryTrade> trades;
		try
		{
			trades = gson.fromJson(raw, TRADE_LIST_TYPE);
		}
		catch (JsonSyntaxException e)
		{
			log.debug("Could not parse RuneLite GE tradeHistory", e);
			return;
		}

		if (trades == null || trades.isEmpty())
		{
			return;
		}

		String accountHashValue = String.valueOf(accountHash);
		String displayName = client.getLocalPlayer() != null
			? client.getLocalPlayer().getName()
			: null;

		Instant watermark = readWatermark(accountHashValue);
		Instant cutoff;
		if (watermark.equals(Instant.EPOCH))
		{
			// First sync for this Jagex account on this RuneLite install: do not upload the
			// entire profile GE history into a newly paired FlipX account — only trades from
			// pairing onward (plus overlap for clock skew).
			cutoff = initialBackfillCutoff();
		}
		else
		{
			cutoff = watermark.minus(WATERMARK_OVERLAP_MINUTES, ChronoUnit.MINUTES);
		}
		Instant maxTradeTime = watermark;

		int enqueued = 0;
		for (RuneliteHistoryTrade trade : trades)
		{
			Instant occurredAt = trade.time != null ? trade.time : Instant.now();
			if (occurredAt.isBefore(cutoff))
			{
				continue;
			}
			if (occurredAt.isAfter(maxTradeTime))
			{
				maxTradeTime = occurredAt;
			}

			IngestGeEvent event = toIngestEvent(trade, accountHashValue, displayName);
			if (event != null)
			{
				ingestClient.enqueue(event);
				enqueued++;
			}
		}

		if (enqueued > 0)
		{
			log.debug("Enqueued {} RuneLite GE history trade(s) for ingest", enqueued);
			ingestClient.flushAsync();
		}

		if (maxTradeTime.isAfter(watermark))
		{
			writeWatermark(accountHashValue, maxTradeTime);
		}
	}

	private Instant initialBackfillCutoff()
	{
		String pairedAt = config.pairedAt();
		if (pairedAt != null && !pairedAt.isBlank())
		{
			try
			{
				return Instant.parse(pairedAt).minus(WATERMARK_OVERLAP_MINUTES, ChronoUnit.MINUTES);
			}
			catch (RuntimeException ignored)
			{
				// fall through
			}
		}
		return Instant.now().minus(WATERMARK_OVERLAP_MINUTES, ChronoUnit.MINUTES);
	}

	private Instant readWatermark(String accountHash)
	{
		String raw = configManager.getConfiguration(
			FlipFinderConfig.GROUP,
			WATERMARK_CONFIG_KEY + "." + accountHash
		);
		if (raw == null || raw.isBlank())
		{
			return Instant.EPOCH;
		}
		try
		{
			return Instant.parse(raw);
		}
		catch (RuntimeException e)
		{
			return Instant.EPOCH;
		}
	}

	private void writeWatermark(String accountHash, Instant instant)
	{
		configManager.setConfiguration(
			FlipFinderConfig.GROUP,
			WATERMARK_CONFIG_KEY + "." + accountHash,
			instant.toString()
		);
	}

	private IngestGeEvent toIngestEvent(
		RuneliteHistoryTrade trade,
		String accountHash,
		String displayName
	)
	{
		if (trade == null || trade.itemId <= 0 || trade.quantity <= 0 || trade.price <= 0)
		{
			return null;
		}

		Instant occurredAt = trade.time != null ? trade.time : Instant.now();
		long epochSecond = occurredAt.getEpochSecond();
		boolean buy = trade.buy;
		String side = buy ? "buy" : "sell";
		String state = buy ? "bought" : "sold";

		String itemName = null;
		try
		{
			itemName = itemManager.getItemComposition(trade.itemId).getName();
		}
		catch (RuntimeException ignored)
		{
			// item metadata optional
		}

		String idempotencyKey = IdempotencyKeyBuilder.importHistory(
			accountHash,
			trade.itemId,
			side,
			trade.price,
			trade.quantity,
			state,
			epochSecond
		);

		return IngestGeEvent.builder()
			.idempotencyKey(idempotencyKey)
			.accountHash(accountHash)
			.accountDisplayName(displayName)
			.itemId(trade.itemId)
			.itemName(itemName)
			.side(side)
			.price(trade.price)
			.quantity(trade.quantity)
			.quantityFilled(trade.quantity)
			.state(state)
			.occurredAt(occurredAt.toString())
			.source("import_runelite_ge")
			.build();
	}

	static final class RuneliteHistoryTrade
	{
		boolean buy;
		int itemId;
		int quantity;
		int price;
		Instant time;

		static List<RuneliteHistoryTrade> empty()
		{
			return Collections.emptyList();
		}
	}
}

package com.osrsflipfinder.runelite;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

@Slf4j
@Singleton
public class IngestClient
{
	static final int MAX_QUEUE_SIZE = 1000;
	static final int FLUSH_THRESHOLD = 50;
	static final int FLUSH_INTERVAL_SECONDS = 8;
	static final int MAX_BATCH_SIZE = 500;
	static final int MAX_BACKOFF_SECONDS = 120;

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient httpClient;
	private final FlipFinderConfig config;
	private final ConfigManager configManager;
	private final OpportunitiesClient opportunitiesClient;
	private final ScheduledExecutorService executorService;
	private final Gson gson;
	private final ConcurrentLinkedQueue<IngestGeEvent> queue = new ConcurrentLinkedQueue<>();
	private final AtomicBoolean flushInProgress = new AtomicBoolean(false);

	private volatile Consumer<SyncStats> syncStatsListener = stats -> {};
	private volatile Consumer<PluginState> stateListener = state -> {};
	private volatile Consumer<String> errorListener = message -> {};

	private ScheduledFuture<?> flushTask;
	private volatile boolean shuttingDown = false;
	private volatile int consecutiveFailures = 0;
	private volatile long retryAfterMs = 0;

	@Inject
	IngestClient(
		OkHttpClient httpClient,
		FlipFinderConfig config,
		ConfigManager configManager,
		OpportunitiesClient opportunitiesClient,
		ScheduledExecutorService executorService,
		Gson gson
	)
	{
		this.httpClient = httpClient;
		this.config = config;
		this.configManager = configManager;
		this.opportunitiesClient = opportunitiesClient;
		this.executorService = executorService;
		this.gson = gson;
	}

	void start()
	{
		shuttingDown = false;
		if (flushTask != null)
		{
			return;
		}
		flushTask = executorService.scheduleWithFixedDelay(
			this::flushAsync,
			FLUSH_INTERVAL_SECONDS,
			FLUSH_INTERVAL_SECONDS,
			TimeUnit.SECONDS
		);
	}

	void shutdown()
	{
		shuttingDown = true;
		if (flushTask != null)
		{
			flushTask.cancel(false);
			flushTask = null;
		}

		for (int attempt = 0; attempt < 3 && !queue.isEmpty() && isConfigured(); attempt++)
		{
			try
			{
				flushNow();
			}
			catch (RuntimeException e)
			{
				log.warn("Shutdown flush attempt {} failed", attempt + 1, e);
			}
		}
	}

	void setSyncStatsListener(Consumer<SyncStats> listener)
	{
		this.syncStatsListener = listener != null ? listener : stats -> {};
	}

	void setStateListener(Consumer<PluginState> listener)
	{
		this.stateListener = listener != null ? listener : state -> {};
	}

	void setErrorListener(Consumer<String> listener)
	{
		this.errorListener = listener != null ? listener : message -> {};
	}

	boolean isConfigured()
	{
		if (!config.enableUpload() || config.apiKey().isBlank())
		{
			return false;
		}
		PluginEntitlements entitlements = opportunitiesClient.getEntitlements();
		return entitlements != null && entitlements.isPluginSync();
	}

	int getQueueSize()
	{
		return queue.size();
	}

	void enqueue(IngestGeEvent event)
	{
		if (!isConfigured() || shuttingDown)
		{
			return;
		}

		if (queue.size() >= MAX_QUEUE_SIZE)
		{
			queue.poll();
			log.warn("Ingest queue full; dropped oldest event");
		}

		queue.add(event);
		if (queue.size() >= FLUSH_THRESHOLD)
		{
			flushAsync();
		}
	}

	void reconcileSlots(String accountHash, String accountDisplayName, java.util.List<GeSlotSnapshot> slots)
	{
		if (!isConfigured() || shuttingDown || slots == null || slots.isEmpty())
		{
			return;
		}

		executorService.execute(() ->
		{
			try
			{
				postReconcile(accountHash, accountDisplayName, slots);
			}
			catch (IOException e)
			{
				log.debug("GE reconcile failed", e);
			}
		});
	}

	private void postReconcile(
		String accountHash,
		String accountDisplayName,
		java.util.List<GeSlotSnapshot> slots
	) throws IOException
	{
		JsonObject root = new JsonObject();
		root.addProperty("accountHash", accountHash);
		if (accountDisplayName != null && !accountDisplayName.isBlank())
		{
			root.addProperty("accountDisplayName", accountDisplayName);
		}

		JsonArray slotArray = new JsonArray();
		for (GeSlotSnapshot snapshot : slots)
		{
			JsonObject entry = new JsonObject();
			entry.addProperty("slot", snapshot.getSlot());
			entry.addProperty("empty", snapshot.isEmpty());
			slotArray.add(entry);
		}
		root.add("slots", slotArray);

		Request request = new Request.Builder()
			.url(FlipXConstants.baseUrl() + "/api/ingest/ge-reconcile")
			.addHeader("Authorization", "Bearer " + config.apiKey())
			.post(RequestBody.create(JSON, gson.toJson(root)))
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			if (!response.isSuccessful())
			{
				ResponseBody responseBody = response.body();
				String raw = responseBody != null ? responseBody.string() : "";
				log.debug("GE reconcile returned {}: {}", response.code(), raw);
			}
		}
	}

	void flushAsync()
	{
		if (!isConfigured() || queue.isEmpty() || shuttingDown)
		{
			return;
		}

		if (System.currentTimeMillis() < retryAfterMs)
		{
			return;
		}

		if (!flushInProgress.compareAndSet(false, true))
		{
			return;
		}

		executorService.execute(() ->
		{
			try
			{
				flushNow();
			}
			finally
			{
				flushInProgress.set(false);
			}
		});
	}

	private void flushNow()
	{
		List<IngestGeEvent> batch = new ArrayList<>();
		while (batch.size() < MAX_BATCH_SIZE)
		{
			IngestGeEvent event = queue.poll();
			if (event == null)
			{
				break;
			}
			batch.add(event);
		}

		if (batch.isEmpty())
		{
			return;
		}

		stateListener.accept(PluginState.SYNCING);

		try
		{
			IngestResult result = postBatch(batch);
			consecutiveFailures = 0;
			retryAfterMs = 0;
			syncStatsListener.accept(new SyncStats(
				Instant.now(),
				result.inserted,
				result.skipped,
				result.total
			));
			stateListener.accept(PluginState.CONNECTED);
			errorListener.accept(null);
		}
		catch (IngestAuthException e)
		{
			requeueFront(batch);
			consecutiveFailures = 0;
			retryAfterMs = 0;
			if (e.getState() == PluginState.REPAIR_REQUIRED)
			{
				PairingCredentials.clearIfAuthFailedForKey(configManager, config, e.getApiKeyUsed());
			}
			stateListener.accept(e.getState());
			errorListener.accept(e.getMessage());
		}
		catch (IngestPermanentException e)
		{
			consecutiveFailures = 0;
			retryAfterMs = 0;
			stateListener.accept(PluginState.ERROR);
			errorListener.accept(e.getMessage());
			log.error("Permanent ingest failure; dropped {} events", batch.size(), e);
		}
		catch (IOException e)
		{
			requeueFront(batch);
			consecutiveFailures++;
			int backoffSeconds = Math.min(
				FLUSH_INTERVAL_SECONDS * (1 << Math.min(consecutiveFailures, 4)),
				MAX_BACKOFF_SECONDS
			);
			retryAfterMs = System.currentTimeMillis() + (backoffSeconds * 1000L);
			stateListener.accept(PluginState.ERROR);
			errorListener.accept(e.getMessage() + " (retry in " + backoffSeconds + "s)");
			log.warn("Ingest failed; will retry in {}s", backoffSeconds, e);
		}
	}

	private IngestResult postBatch(List<IngestGeEvent> batch) throws IOException
	{
		String apiKeyUsed = config.apiKey();
		JsonObject root = new JsonObject();
		JsonArray events = new JsonArray();
		for (IngestGeEvent event : batch)
		{
			events.add(gson.toJsonTree(event));
		}
		root.add("events", events);

		Request request = new Request.Builder()
			.url(FlipXConstants.baseUrl() + "/api/ingest/ge-events")
			.addHeader("Authorization", "Bearer " + apiKeyUsed)
			.post(RequestBody.create(JSON, gson.toJson(root)))
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody responseBody = response.body();
			String raw = responseBody != null ? responseBody.string() : "";

			if (response.code() == 401)
			{
				throw new IngestAuthException(
					PluginState.REPAIR_REQUIRED,
					"Invalid API key - re-pair required",
					apiKeyUsed
				);
			}

			if (response.code() == 403)
			{
				String code = parseErrorCode(raw);
				if ("linked_account_limit".equals(code))
				{
					String message = parseErrorMessage(raw,
						"Free plan supports one OSRS account. Upgrade at flipx.gg/pricing or log into your linked account.");
					throw new IngestPermanentException(message);
				}
				String message = humanizeUpgradeMessage(parseErrorMessage(raw, "Pro subscription required for plugin sync"));
				throw new IngestAuthException(PluginState.UPGRADE_REQUIRED, message, apiKeyUsed);
			}

			if (response.code() == 400)
			{
				String message = parseErrorMessage(raw, "Invalid event data - sync paused");
				throw new IngestPermanentException(message);
			}

			if (response.code() == 429)
			{
				String message = parseErrorMessage(raw, "Rate limited - backing off");
				throw new IOException(message);
			}

			if (response.code() >= 500)
			{
				String message = parseErrorMessage(raw, "Server error (" + response.code() + ")");
				throw new IOException(message);
			}

			if (!response.isSuccessful())
			{
				String message = parseErrorMessage(raw, "Ingest failed (" + response.code() + ")");
				throw new IOException(message);
			}

			JsonObject parsed = new JsonParser().parse(raw).getAsJsonObject();
			return new IngestResult(
				parsed.has("inserted") ? parsed.get("inserted").getAsInt() : 0,
				parsed.has("skipped") ? parsed.get("skipped").getAsInt() : 0,
				parsed.has("total") ? parsed.get("total").getAsInt() : batch.size()
			);
		}
	}

	private void requeueFront(List<IngestGeEvent> batch)
	{
		for (int i = batch.size() - 1; i >= 0; i--)
		{
			queue.add(batch.get(i));
		}
	}

	private static String parseErrorCode(String raw)
	{
		try
		{
			JsonObject parsed = new JsonParser().parse(raw).getAsJsonObject();
			if (parsed.has("code"))
			{
				return parsed.get("code").getAsString();
			}
		}
		catch (RuntimeException ignored)
		{
			// fall through
		}
		return "";
	}

	private static String parseErrorMessage(String raw, String fallback)
	{
		try
		{
			JsonObject parsed = new JsonParser().parse(raw).getAsJsonObject();
			if (parsed.has("error"))
			{
				return parsed.get("error").getAsString();
			}
		}
		catch (RuntimeException ignored)
		{
			// fall through
		}
		return fallback;
	}

	private static String humanizeUpgradeMessage(String message)
	{
		if (message == null || message.isBlank() || "upgrade_required".equals(message))
		{
			return "FlipX could not verify your subscription. Refresh billing on the web app, then try Connect again.";
		}
		return message;
	}

	@Value
	static class IngestResult
	{
		int inserted;
		int skipped;
		int total;
	}

	@Value
	public static class SyncStats
	{
		Instant syncedAt;
		int inserted;
		int skipped;
		int total;
	}

	private static final class IngestAuthException extends IOException
	{
		private final PluginState state;
		private final String apiKeyUsed;

		private IngestAuthException(PluginState state, String message, String apiKeyUsed)
		{
			super(message);
			this.state = state;
			this.apiKeyUsed = apiKeyUsed;
		}

		private PluginState getState()
		{
			return state;
		}

		private String getApiKeyUsed()
		{
			return apiKeyUsed;
		}
	}

	private static final class IngestPermanentException extends IOException
	{
		private IngestPermanentException(String message)
		{
			super(message);
		}
	}
}

package com.osrsflipfinder.runelite;

import net.runelite.api.Client;
import net.runelite.api.VarClientInt;
import net.runelite.api.VarClientStr;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;

/**
 * Prefills the GE Enter-price / Enter-quantity chatbox. Same pattern as Flipping Copilot:
 * set the visible input text; the user still presses Enter and Confirms the offer.
 */
final class GeOfferChatInput
{
	static final int CHAT_INPUT_TYPE_GE = 7;

	enum Step
	{
		NONE,
		PRICE,
		QUANTITY_BUY,
		QUANTITY_SELL
	}

	private GeOfferChatInput()
	{
	}

	static boolean isOpen(Client client)
	{
		return client.getVarcIntValue(VarClientInt.INPUT_TYPE) == CHAT_INPUT_TYPE_GE
			|| client.getVarcIntValue(VarClientID.MESLAYERMODE) == CHAT_INPUT_TYPE_GE;
	}

	/**
	 * True when some other chat/meslayer input is open (not the GE price/qty box).
	 * Assist must not prefill or remember a value through that.
	 */
	static boolean isOtherInputOpen(Client client)
	{
		int inputType = client.getVarcIntValue(VarClientInt.INPUT_TYPE);
		int mesMode = client.getVarcIntValue(VarClientID.MESLAYERMODE);
		if (inputType == 0 && mesMode == 0)
		{
			return false;
		}
		return !isOpen(client);
	}

	static String readPrompt(Client client)
	{
		Widget mesText = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		return mesText != null ? mesText.getText() : null;
	}

	static Step parseStep(String chatPrompt)
	{
		if (chatPrompt == null)
		{
			return Step.NONE;
		}
		if ("Set a price for each item:".equals(chatPrompt))
		{
			return Step.PRICE;
		}
		String lower = chatPrompt.toLowerCase();
		if (lower.contains("how many do you wish to buy"))
		{
			return Step.QUANTITY_BUY;
		}
		if (lower.contains("how many do you wish to sell"))
		{
			return Step.QUANTITY_SELL;
		}
		return Step.NONE;
	}

	static Step currentStep(Client client)
	{
		if (!isOpen(client))
		{
			return Step.NONE;
		}
		return parseStep(readPrompt(client));
	}

	static boolean isPriceOpen(Client client)
	{
		return currentStep(client) == Step.PRICE;
	}

	static boolean isQuantityOpen(Client client)
	{
		Step step = currentStep(client);
		return step == Step.QUANTITY_BUY || step == Step.QUANTITY_SELL;
	}

	static void prefill(Client client, int value)
	{
		if (client == null || value <= 0)
		{
			return;
		}
		String text = String.valueOf(value);
		Widget mesText2 = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (mesText2 != null)
		{
			mesText2.setText(value + "*");
		}
		client.setVarcStrValue(VarClientStr.INPUT_TEXT, text);
	}

	/** Prefills only when the open GE chat matches {@code required}. */
	static boolean prefillIfStep(Client client, int value, Step required)
	{
		if (client == null || value <= 0 || required == null || required == Step.NONE)
		{
			return false;
		}
		Step actual = currentStep(client);
		if (required == Step.PRICE && actual != Step.PRICE)
		{
			return false;
		}
		if ((required == Step.QUANTITY_BUY || required == Step.QUANTITY_SELL)
			&& actual != Step.QUANTITY_BUY
			&& actual != Step.QUANTITY_SELL)
		{
			return false;
		}
		prefill(client, value);
		return true;
	}
}

