package com.osrsflipfinder.runelite;

/** Maps unified item detail into the copilot overlay shape. */
final class ItemCopilotMapper
{
	private ItemCopilotMapper()
	{
	}

	static CopilotItem from(FlipOpportunity opp, long updatedAtMs)
	{
		return from(opp, updatedAtMs, null);
	}

	static CopilotItem from(
		FlipOpportunity opp,
		long updatedAtMs,
		ItemDetailResponse.MarketRegimeSummary regime)
	{
		CopilotItem item = new CopilotItem();
		item.setItemId(opp.getId());
		item.setName(opp.getName());
		item.setEstimatedBuyPrice(opp.getEstimatedBuyPrice());
		item.setEstimatedSellPrice(opp.getEstimatedSellPrice());
		item.setOpportunityScore(opp.getOpportunityScore());
		item.setConfidenceScore(opp.getConfidenceScore());
		item.setNetProfitPerItem(opp.getNetProfitPerItem());
		item.setNetRoiPercent(opp.getNetRoiPercent());
		item.setReferenceTradingPrice(
			opp.getReferenceTradingPrice() != null ? opp.getReferenceTradingPrice().longValue() : 0L
		);
		item.setGeGuidePrice(opp.getGeGuidePrice());
		item.setUpdatedAt(updatedAtMs);
		item.setInstantBuyPrice(opp.getEstimatedSellPrice());
		item.setInstantSellPrice(opp.getEstimatedBuyPrice());
		item.setRepriceHint(FlipCopilotPresenter.repriceHint(opp));
		item.setPriceIssue(null);
		item.setDeltaPercent(null);
		item.setVerdict(FlipCopilotPresenter.verdict(opp).name().toLowerCase());
		item.setActionSummary(FlipCopilotPresenter.actionSummary(opp));
		if (regime != null)
		{
			item.setRiskRegimeState(regime.getState());
			item.setRiskWarning(regime.getWarning());
		}
		return item;
	}

	static CopilotItem from(ItemDetailResponse detail)
	{
		if (detail == null || detail.getOpportunity() == null)
		{
			return null;
		}
		long updatedAt = detail.getMeta() != null ? detail.getMeta().getLastUpdatedMs() : 0L;
		return from(detail.getOpportunity(), updatedAt, detail.getMarketRegime());
	}
}

package com.osrsflipfinder.runelite;

/** Client poll scheduling aligned with {@code src/lib/osrs/wiki-clock.ts}. */
final class ClientSchedule
{
	static final double PHASE_CONFIDENCE_THRESHOLD = 0.35;

	private ClientSchedule()
	{
	}

	static long computeNextFetchAtMs(
		MarketQueryResponse.Meta meta,
		long publishLeadMs,
		long fallbackIntervalMs,
		long nowMs
	)
	{
		if (meta == null)
		{
			return nowMs + Math.max(0, fallbackIntervalMs);
		}
		return computeNextFetchAtMs(
			meta.getNextWikiPublishAtMs(),
			meta.getNextPublishInMs(),
			meta.getPhaseConfidence(),
			publishLeadMs,
			fallbackIntervalMs,
			nowMs
		);
	}

	static long computeNextFetchAtMs(
		ItemDetailResponse.ItemDetailMeta meta,
		long publishLeadMs,
		long fallbackIntervalMs,
		long nowMs
	)
	{
		if (meta == null)
		{
			return nowMs + Math.max(0, fallbackIntervalMs);
		}
		return computeNextFetchAtMs(
			meta.getNextWikiPublishAtMs(),
			meta.getNextPublishInMs(),
			meta.getPhaseConfidence(),
			publishLeadMs,
			fallbackIntervalMs,
			nowMs
		);
	}

	private static long computeNextFetchAtMs(
		Long nextWikiPublishAtMs,
		Long nextPublishInMs,
		double phaseConfidence,
		long publishLeadMs,
		long fallbackIntervalMs,
		long nowMs
	)
	{
		long fallback = nowMs + Math.max(0, fallbackIntervalMs);

		if (nextWikiPublishAtMs != null
			&& nextWikiPublishAtMs > 0
			&& phaseConfidence >= PHASE_CONFIDENCE_THRESHOLD)
		{
			long aligned = nextWikiPublishAtMs + publishLeadMs;
			if (aligned > nowMs)
			{
				return aligned;
			}
		}

		if (phaseConfidence >= PHASE_CONFIDENCE_THRESHOLD
			&& nextPublishInMs != null
			&& nextPublishInMs >= 0)
		{
			if (nextPublishInMs <= publishLeadMs)
			{
				return fallback;
			}
			return nowMs + nextPublishInMs + publishLeadMs;
		}

		return fallback;
	}

	/** Decay frozen publish countdown (matches web {@code adjustPublishMetaForClient}). */
	static ItemDetailResponse.ItemDetailMeta decayItemMeta(
		ItemDetailResponse.ItemDetailMeta meta,
		long storedAtMs,
		long nowMs
	)
	{
		if (meta == null)
		{
			return null;
		}

		double conf = meta.getPhaseConfidence();
		if (conf < PHASE_CONFIDENCE_THRESHOLD)
		{
			return meta;
		}

		Long wikiAt = meta.getNextWikiPublishAtMs();
		if (wikiAt != null && wikiAt > 0)
		{
			ItemDetailResponse.ItemDetailMeta adjusted = copyMeta(meta);
			adjusted.setNextPublishInMs(Math.max(0L, wikiAt - nowMs));
			return adjusted;
		}

		Long nextIn = meta.getNextPublishInMs();
		if (nextIn == null)
		{
			return meta;
		}

		long elapsed = Math.max(0L, nowMs - storedAtMs);
		ItemDetailResponse.ItemDetailMeta adjusted = copyMeta(meta);
		adjusted.setNextPublishInMs(Math.max(0L, nextIn - elapsed));
		return adjusted;
	}

	private static ItemDetailResponse.ItemDetailMeta copyMeta(ItemDetailResponse.ItemDetailMeta meta)
	{
		ItemDetailResponse.ItemDetailMeta copy = new ItemDetailResponse.ItemDetailMeta();
		copy.setChartDays(meta.getChartDays());
		copy.setLastUpdatedMs(meta.getLastUpdatedMs());
		copy.setNextPublishInMs(meta.getNextPublishInMs());
		copy.setNextWikiPublishAtMs(meta.getNextWikiPublishAtMs());
		copy.setPhaseConfidence(meta.getPhaseConfidence());
		return copy;
	}

	static long msUntilNextFetch(long nextFetchAtMs, long nowMs)
	{
		return Math.max(0, nextFetchAtMs - nowMs);
	}
}

