package com.osrsflipfinder.runelite;

import javax.annotation.Nullable;

/** Wiki-aligned buy/sell resolution for overlay and GE assist. */
final class DisplayPriceResolver
{
	private DisplayPriceResolver()
	{
	}

	static long resolveBuyPrice(@Nullable ItemDetailResponse detail, @Nullable PluginEntitlements entitlements)
	{
		return resolveSide(detail, true);
	}

	static long resolveSellPrice(@Nullable ItemDetailResponse detail, @Nullable PluginEntitlements entitlements)
	{
		return resolveSide(detail, false);
	}

	static GeAssistPricing.PriceSource resolveBuySource(
		@Nullable ItemDetailResponse detail,
		@Nullable PluginEntitlements entitlements
	)
	{
		return resolveSideSource(detail, true);
	}

	static GeAssistPricing.PriceSource resolveSellSource(
		@Nullable ItemDetailResponse detail,
		@Nullable PluginEntitlements entitlements
	)
	{
		return resolveSideSource(detail, false);
	}

	private static long resolveSide(ItemDetailResponse detail, boolean buy)
	{
		if (detail == null || detail.getOpportunity() == null)
		{
			return 0;
		}
		FlipOpportunity opp = detail.getOpportunity();
		DisplayPricesResponse dp = opp.getDisplayPrices();
		if (dp != null && dp.getBuyPrice() > 0 && dp.getSellPrice() > 0)
		{
			return buy ? dp.getBuyPrice() : dp.getSellPrice();
		}
		return buy ? opp.getEstimatedBuyPrice() : opp.getEstimatedSellPrice();
	}

	private static GeAssistPricing.PriceSource resolveSideSource(ItemDetailResponse detail, boolean buy)
	{
		if (detail == null || detail.getOpportunity() == null)
		{
			return GeAssistPricing.PriceSource.WIKI;
		}
		DisplayPricesResponse dp = detail.getOpportunity().getDisplayPrices();
		if (dp != null && "network".equalsIgnoreCase(dp.getSource()))
		{
			return GeAssistPricing.PriceSource.NETWORK;
		}
		return GeAssistPricing.PriceSource.WIKI;
	}

	static long resolveNetProfit(ItemDetailResponse detail)
	{
		if (detail == null || detail.getOpportunity() == null)
		{
			return 0;
		}
		DisplayPricesResponse dp = detail.getOpportunity().getDisplayPrices();
		if (dp != null)
		{
			return dp.getNetProfitPerItem();
		}
		return detail.getOpportunity().getNetProfitPerItem();
	}

	static double resolveNetRoi(ItemDetailResponse detail)
	{
		if (detail == null || detail.getOpportunity() == null)
		{
			return 0;
		}
		DisplayPricesResponse dp = detail.getOpportunity().getDisplayPrices();
		if (dp != null)
		{
			return dp.getNetRoiPercent();
		}
		return detail.getOpportunity().getNetRoiPercent();
	}

	static String overlayBuyLabel(GeAssistPricing.PriceSource source)
	{
		return "Buy";
	}

	static String overlaySellLabel(GeAssistPricing.PriceSource source)
	{
		return "Sell";
	}
}

package com.osrsflipfinder.runelite;

import java.awt.Dimension;
import javax.swing.JComponent;
import javax.swing.JPanel;
import net.runelite.client.ui.PluginPanel;

/**
 * Panel constrained to the RuneLite sidebar content column ({@link PluginPanel#PANEL_WIDTH}).
 * Height is allowed to grow - never lock max height to preferred height.
 */
class SidebarContentPanel extends JPanel
{
	static final int CONTENT_WIDTH = PluginPanel.PANEL_WIDTH;
	/** Width for stacked controls inside {@link PluginUi#pageInsets()} - avoids clipping at panel edges. */
	static final int INNER_WIDTH = CONTENT_WIDTH - (2 * PluginPanel.BORDER_OFFSET);

	@Override
	public Dimension getPreferredSize()
	{
		Dimension size = super.getPreferredSize();
		return new Dimension(CONTENT_WIDTH, size.height);
	}

	@Override
	public Dimension getMaximumSize()
	{
		return new Dimension(CONTENT_WIDTH, Short.MAX_VALUE);
	}

	@Override
	public Dimension getMinimumSize()
	{
		Dimension size = super.getMinimumSize();
		return new Dimension(CONTENT_WIDTH, size.height);
	}

	static void lockWidth(JComponent component)
	{
		component.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		component.setMaximumSize(new Dimension(INNER_WIDTH, Short.MAX_VALUE));
	}

	static void lockWidthFixed(JComponent component, int height)
	{
		component.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		Dimension size = new Dimension(INNER_WIDTH, height);
		component.setPreferredSize(size);
		component.setMinimumSize(size);
		component.setMaximumSize(size);
	}
}

package com.osrsflipfinder.runelite;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;

/**
 * Mirrors Flipping Utilities {@code HistoryManager.deletePreviousOffersForTrade} so we
 * store one row per GE trade instead of every progress tick.
 */
@Singleton
public class GeOfferHistoryCompressor
{
	private final Map<String, List<IngestGeEvent>> compressedByAccountItem = new HashMap<>();

	void resetForAccount(String accountHash)
	{
		compressedByAccountItem.keySet().removeIf(key -> key.startsWith(accountHash + ":"));
	}

	IngestGeEvent compressAndTrack(IngestGeEvent incoming)
	{
		if (incoming == null || incoming.getSlot() == null)
		{
			return incoming;
		}

		String key = incoming.getAccountHash() + ":" + incoming.getItemId();
		List<IngestGeEvent> compressed = compressedByAccountItem.computeIfAbsent(
			key,
			k -> new ArrayList<>()
		);

		deletePreviousOffersForTrade(compressed, incoming);
		compressed.add(copy(incoming));
		return incoming;
	}

	private static void deletePreviousOffersForTrade(
		List<IngestGeEvent> compressed,
		IngestGeEvent incoming
	)
	{
		Integer incomingSlot = incoming.getSlot();
		if (incomingSlot == null)
		{
			return;
		}

		for (int i = compressed.size() - 1; i >= 0; i--)
		{
			IngestGeEvent previous = compressed.get(i);

			if (isUpdateForCancelled(incoming, previous))
			{
				compressed.remove(i);
				continue;
			}

			Integer previousSlot = previous.getSlot();
			if (previousSlot != null
				&& previousSlot.equals(incomingSlot)
				&& previous.getSide().equals(incoming.getSide()))
			{
				if (isComplete(previous.getState()))
				{
					return;
				}
				compressed.remove(i);
			}
		}
	}

	private static boolean isComplete(String state)
	{
		return "bought".equals(state)
			|| "sold".equals(state)
			|| "cancelled_buy".equals(state)
			|| "cancelled_sell".equals(state);
	}

	private static boolean isRedundantProgressBeforeCompletion(IngestGeEvent event)
	{
		String state = event.getState();
		if (!"buying".equals(state) && !"selling".equals(state))
		{
			return false;
		}
		return event.getQuantityFilled() > 0 && event.getQuantityFilled() == event.getQuantity();
	}

	static boolean isUpdateForCancelled(IngestGeEvent newer, IngestGeEvent older)
	{
		boolean newerProgress = "buying".equals(newer.getState()) || "selling".equals(newer.getState());
		boolean olderCancelled = "cancelled_buy".equals(older.getState())
			|| "cancelled_sell".equals(older.getState());
		if (!newerProgress || !olderCancelled)
		{
			return false;
		}
		if (newer.getSlot() == null || older.getSlot() == null || !newer.getSlot().equals(older.getSlot()))
		{
			return false;
		}
		if (!newer.getSide().equals(older.getSide()))
		{
			return false;
		}
		if (newer.getQuantity() != older.getQuantity())
		{
			return false;
		}
		if (newer.getPrice() != older.getPrice())
		{
			return false;
		}
		return newer.getQuantityFilled() != older.getQuantityFilled();
	}

	static IngestGeEvent copy(IngestGeEvent source)
	{
		return IngestGeEvent.builder()
			.idempotencyKey(source.getIdempotencyKey())
			.accountHash(source.getAccountHash())
			.accountDisplayName(source.getAccountDisplayName())
			.itemId(source.getItemId())
			.itemName(source.getItemName())
			.side(source.getSide())
			.price(source.getPrice())
			.quantity(source.getQuantity())
			.quantityFilled(source.getQuantityFilled())
			.state(source.getState())
			.occurredAt(source.getOccurredAt())
			.slot(source.getSlot())
			.source(source.getSource())
			.build();
	}

	boolean shouldSkipDuplicateProgress(IngestGeEvent event)
	{
		return isRedundantProgressBeforeCompletion(event);
	}
}

